INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Double Dragon Advance', 'Double Dragon Advance is a side-scrolling beat ''em up game developed by Million and published by Atlus for the Game Boy Advance. Released in 2003, it serves as an enhanced remake of the original Double Dragon arcade game, incorporating elements from the entire Double Dragon series. The game follows brothers Billy and Jimmy Lee as they battle through various stages to rescue Marian from a dangerous gang. It features new levels, enemies, and moves not found in the original version, along with improved graphics and expanded combat mechanics.' FROM games WHERE igdb_id = 6384 ON CONFLICT (game_id, language_code) DO NOTHING;
