INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('railroad-pioneer', 9417, '2003-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3y94.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkjv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Railroad Pioneer', 'Join us on a Journey into History and Adventure. Be a pioneer and build the most famous transcontinental railroad tracks in the United States of America throughout the 19th century. Our Journey starts in the city of New York around the year 1830. Discover the famous trail of the railroad pioneers to the sunny east coast. Experience the Dangers and Challenges of those times and enter one of the biggest Adventures in the history of the Railroad. In Railroad Pioneer you are invited to explore these famous routes step by step. Learn about the fantastic history of discovering the west of America and see if you have what it takes to be successful.' FROM games WHERE igdb_id = 9417 ON CONFLICT (game_id, language_code) DO NOTHING;
