INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haegemonia: The Solon Heritage', 'As a stand-alone expansion pack to Legions of Iron, discover new innovations and even more stunning visuals that launch the Haegemonia experience into light speed. The Solon Heritage is a multiplayer-only package with over 70 new inventions, all new skills and heroes, new spaceships and strategy options with an all-improved AI. Colonize, conquer, conduct research, trade, spy and battle it out … but be diplomatic or extinction of your race is inevitable.' FROM games WHERE igdb_id = 17299 ON CONFLICT (game_id, language_code) DO NOTHING;
