INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('swordsman-online', 9738, '2003-01-01', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rktixu3n7tqzknpfxw45.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yv78wp2fum5i109hen1z.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swordsman Online', 'Swordsman gameplay has a focus on action-oriented combat that is less focused on stats and more on player skill. Players can excel through character mobility, aerial combat, twitch reflexes, dodging, and dynamic combat styles inspired by martial arts. Zones dynamically transform as a result of player actions and the actions of player guilds. As players move through the main story, the environment may change based on their decisions. Towns will be destroyed or saved, new NPCs and quest givers will appear, and secret rooms will be revealed. Players can see the effects of their decisions reflected in the balance between good and evil in each zone. Although was born in China, Swordsman Online aka Võ Lâm Truyền Kỳ became  a major hit of Vietnamese gaming community early 2000s. It survives until now and has 9 major update patches including Võ Lâm Truyền Kỳ 2 and several visual and gameplay improvement.' FROM games WHERE igdb_id = 9738 ON CONFLICT (game_id, language_code) DO NOTHING;
