INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MapleStory', 'Welcome to MapleStory, the original side-scrolling MMORPG where epic adventure, action and good friends await you. With hundreds of hours of gameplay, this immersive role-playing experience will allow you to unleash your wild side as you create and train a mighty hero, conquer perilous dungeons, overcome terrifying bosses, socialize with your friends and much more. Your MapleStory begins today!' FROM games WHERE igdb_id = 9804 ON CONFLICT (game_id, language_code) DO NOTHING;
