INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Konga', 'Donkey Konga is a GameCube rhythm video game starring the ape Donkey Kong, developed by Namco and published by Nintendo. Instead of the standard GameCube controllers, the game is intended to be played with a special controller called the DK Bongos that resemble two small bongo drums. Donkey Konga was developed by the same team of people who made the Taiko: Drum Master series for the PlayStation 2. The tracks include hits such as "Louie Louie", "We Will Rock You", "Shining Star", "Rock Lobster" and "Losing My Religion". There are tracks from the Mario series, the The Legend of Zelda series and other Nintendo related music. All regional variants of the game have differing track listings, and in the North American version of both games, almost all of the licensed non-Nintendo/traditional songs are shortened covers.' FROM games WHERE igdb_id = 3889 ON CONFLICT (game_id, language_code) DO NOTHING;
