INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider: The Angel of Darkness', 'Tomb Raider: The Angel of Darkness is the sixth game in the Tomb Raider series, and is the sequel to Tomb Raider: Chronicles. Angel of Darkness introduces new stealth and close-combat moves - ducking, sneaking and hug-the-walls walking. Lara must build her skills by performing action sequences. You''ll have her running, dodging, performing flying leaps and platform jumps, shimming along walls and cables, as well as moving boxes and other obstacles around. Advancements are achieved with strategically placed power-ups. Collect weapons and ammunition, artifacts and money.' FROM games WHERE igdb_id = 1159 ON CONFLICT (game_id, language_code) DO NOTHING;
