INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ribbit-king', 4087, '2003-07-11', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49uj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8bq9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ribbit King', 'The ''Kero Kero'' of the title comes from the onomatopoeia for the sound a frog makes. But no wonder the frog is squawking as it gets hammered around the course in a game of croquet with frogs instead of balls. Various conditions to consider too like in golf such as the wind direction or the fact that the ball is a frog and will jump off spiders webs or launch at passing flies. Allows players to enjoy their own characters in versus mode too.' FROM games WHERE igdb_id = 4087 ON CONFLICT (game_id, language_code) DO NOTHING;
