INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Lord of the Rings: War of the Ring', 'The quest to destroy the One Ring continues in the first real-time strategy game based on The Lord of the Rings saga. Massive battles erupt as the forces of light and darkness fight for control of Middle-earth. The more units you destroy, the more experience and visual enhancements you earn. Play as the forces of good and valiantly fight for the ring''s destruction or play as the forces of evil to claim control over Middle-earth forever.' FROM games WHERE igdb_id = 9256 ON CONFLICT (game_id, language_code) DO NOTHING;
