INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crimson Skies: High Road to Revenge', 'Crimson Skies: High Road to Revenge combines thrilling aerial combat with the swashbuckling style of a Hollywood action-adventure movie. Set in an alternate 1930s world of gunship diplomacy and sinister intrigue, Crimson Skies: High Road to Revenge lets gamers pilot powerful aircraft against nefarious air pirates and behemoth war zeppelins. As the daring air pirate Nathan Zachary, leader of the infamous Fortune Hunters, players take off on a high-flying adventure, filled with daring escapes and damsels in distress.' FROM games WHERE igdb_id = 5793 ON CONFLICT (game_id, language_code) DO NOTHING;
