INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Blast: The Encounter', 'Alien Blast: The Encounter is a first person stationary shooter similar to Made By Kiddies'' previous title, Air Raid. On any given level, the player mans one of the defensive turrets, with a 360 degree view of the area and must blast alien creatures as they appear on the radar. Aliens can come by both land and by air. A friendly spaceship named the UMBK will sometimes arrive to drop power-ups on the battlefield including shield restores, ammo replenishing and new weapons.' FROM games WHERE igdb_id = 24188 ON CONFLICT (game_id, language_code) DO NOTHING;
