INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zuma', 'Survive the ancient temples of Zuma, the critically acclaimed action-puzzler from PopCap! Deep in the jungle lie hidden temples bursting with traps and trickery, and it''s up to you to uncover their treasures. Fire magical balls from your stone frog idol to make matches of three or more and clear the deadly chain before it reaches the golden skull.' FROM games WHERE igdb_id = 3753 ON CONFLICT (game_id, language_code) DO NOTHING;
