INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Budokai 2', 'Go to the next level in the Dragon Ball Z saga. Dragon Ball Z: Budokai 2 improves upon the first installment by adding an all-new single player mode, new characters and explosive attacks. Experience the new match-ups, character cameos and challenging missions in "Dragon World." Pick your favorite DBZ hero or enemy and take on a friend in "Vs." and "Tournament" modes. If you''re really good, you will soon come face-to-face with Buu, the most lethal DBZ villain.' FROM games WHERE igdb_id = 2564 ON CONFLICT (game_id, language_code) DO NOTHING;
