INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil: Dead Aim', 'Resident Evil: Dead Aim is a survival-horror game released exclusively for the PlayStation 2 under the Gun Survivor title, which was used for several games made for the Namco light gun controllers. The game is played in two camera angles: the player moves from a third-person perspective while walking, which changes to a first-person perspective while aiming the gun. You''ll pick up several guns through the course of the game, including a magnum, a shotgun, and an assault rifle. But like in other Resident Evil games, zombies are difficult to put down permanently and ammo can be very scarce.' FROM games WHERE igdb_id = 971 ON CONFLICT (game_id, language_code) DO NOTHING;
