INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('drake-of-the-99-dragons', 5815, '2003-11-03', 30, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3tu9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar35jc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drake of the 99 Dragons', 'Drake of the 99 Dragons (also titled Drake) is a cel-shaded third-person shooter video game developed by Idol FX and published by Majesco Entertainment. It was released for the Xbox on November 3, 2003 and for Microsoft Windows PC systems on June 14, 2004. The game stars Drake, an undead assassin who is on a quest to avenge his murdered clan, the 99 Dragons, by recovering their ancient "Soul Portal Artifact" from antagonist Tang. Tang intends on using the artifact to harvest the souls of dead beings and power his undead cyborg army. Idol FX intended for Drake of the 99 Dragons to be the launchpad for a multimedia franchise, which would include comics and a potential animated television series. However, the contract they signed with Majesco gave them a mere six months for development, leaving little room for play-testing and resulting in the game being unfinished. As a result, it is often considered to be one of the worst games of all-time.' FROM games WHERE igdb_id = 5815 ON CONFLICT (game_id, language_code) DO NOTHING;
