INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chrome', 'You play as Logan, a surly space-faring mercenary in this first-person shooter. Travel from planet to planet working for the highest paying corporation. You not only travel on foot, you can man a variety of different vehicles on the land, air and sea. Chrome adds a neat spin on the first-person shooter realm with features such as an inventory system, cybernetic implants that enhance your abilities and an engaging and cinematic storyline.' FROM games WHERE igdb_id = 7873 ON CONFLICT (game_id, language_code) DO NOTHING;
