INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('one-piece-grand-battle-3', 75752, '2003-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co53r6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sco4wk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Piece: Grand Battle! 3', 'One Piece Grand Battle 3 is a video game of the action-adventure genre released in 2003 by Ganbarion. This is the third game in the Grand Battle series and the sequel to Grand Battle! 2. The game was released only in Japan on December 11, 2003 for the Playstation 2 and Game Cube. The Game cube version of this game featured a demo of One Piece: Going Baseball in which could be played on a Game Boy Advance. Only Luffy and Enel were playable. This game was never translated into English. This game includes sixteen playable characters and seven stages all based on the One Piece story up to the Skypiea Arc. Each character contains over two special attacks, and can use the environment as a weapon.' FROM games WHERE igdb_id = 75752 ON CONFLICT (game_id, language_code) DO NOTHING;
