INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Trek: Elite Force II', 'In this sequel to the first person action game, you resume the role of Alexander Munro, chief of the Hazard Team, Starfleet''s elite security unit. Now assigned to the U.S.S. Enterprise NCC 1701-E, you''ll explore strange new worlds, battle against both new and familiar civilizations and go on the most dangerous assignments in the galaxy. After a brief prologue on the U.S.S. Voyager and a short stint at Starfleet Academy, the Hazard Team is assigned its toughest mission yet - duty onboard the Federation''s renowned flagship, the U.S.S. Enterprise NCC 1701-E.' FROM games WHERE igdb_id = 8420 ON CONFLICT (game_id, language_code) DO NOTHING;
