INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neighbours from Hell', 'Woody is an average man who has a happy life, until his neighbor Mr. Rottweiler, makes his life miserable. So Woody decides to take full revenge on Mr. Rottweiler, becoming the star of a new TV show where he performs tricks on his unsuspecting neighbour, setting traps in his house such as sawing the chair, banana peels/soap on the floor, smeared paintings and messing with home equipment. Create disarray, increase ratings, and win awards as you make a living hell out of the neighbour''s life!' FROM games WHERE igdb_id = 3132 ON CONFLICT (game_id, language_code) DO NOTHING;
