INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Street', 'Gamers of all ages will enjoy the varied puzzle games, board games and other multiplayer party-style competitions in My Street for PlayStation 2. My Street takes place in a sunny, residential neighborhood with chirping birds, barking dogs, picket fences, sidewalks and front porches. Customize your character and then head for the backyard, the basement, the local park, or other neighborhood spots to play 8 different games with up to 3 other characters, including Marbles, Chemistry Set, Volleyball, Pigs and Chickens, Dodge Ball, Corn Field Maze, RC Racing and Lawn Mowers.' FROM games WHERE igdb_id = 19306 ON CONFLICT (game_id, language_code) DO NOTHING;
