INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('capcom-vs-snk-2-eo', 86343, '2003-07-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9djw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8a24.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capcom vs. SNK 2 EO', 'Capcom vs. SNK 2 EO is the same game but with minor changes in gameplay and the inclusion of an EO ("Easy Operation") system that allows the player to perform specific attacks by simply moving the right analog stick in a certain direction. Like all other home versions of the game, CvS2: EO also contains four bonus characters: Evil Ryu, Orochi Iori, Shin Akuma (Shin Gouki in Japan), and Ultimate Rugal (God Rugal in Japan), powered-up versions of four regular characters. Before selecting a team, the game offers a selection of "Grooves", which change the way the game is played, as well as "AC-ism" or "GC-ism" Grooves; GC-ism simplifies the control scheme, originally designed for the GameCube gamepad. In the Xbox version it is called EO-ism. Capcom vs. SNK 2 EO also removed the Roll Cancel glitch that was in the original versions. In addition, the Xbox version of CvS2: EO also included online play for up to two players on Xbox Live as well as progressive-scan (480p) support, which was noticeably absent in the PlayStation 2 version.' FROM games WHERE igdb_id = 86343 ON CONFLICT (game_id, language_code) DO NOTHING;
