INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyond Good & Evil', 'Beyond Good & Evil is an action-adventure game with elements of puzzle-solving and stealth-based games. The player controls the protagonist, Jade, from a third-person perspective. Jade can run, move stealthily, jump over obstacles and pits, climb ladders, push or bash doors and objects, and flatten herself against walls. As Jade, the player investigates a number of installations in search of the truth about a war with an alien threat.' FROM games WHERE igdb_id = 1341 ON CONFLICT (game_id, language_code) DO NOTHING;
