INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lock On: Modern Air Combat', 'Lock On: Modern Air Combat is considered as a survey simulator by its creators. It contains 8 flyable aircraft and over 40 non-playable/AI-controlled planes. The game mainly revolves around air-to-air combat and air-to-ground combat with some optional, unique roles such as pinpoint/anti-radiation strikes, anti-ship strikes or aerobatics. The game realistically models all aspects of take-off and landing, AWACS (also known as AEW&C), carrier-based landings (for the Su-33), and aerial refueling.' FROM games WHERE igdb_id = 10201 ON CONFLICT (game_id, language_code) DO NOTHING;
