INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WarioWare, Inc.: Mega Microgame$!', 'Frantic action! Prepare for lightning-quick game play as you blaze through over 200 bizarre microgames designed by a crazy crew of Wario''s cronies! There are even two-player contests that can be played on a single Game Boy Advance! Pick up and play! Ultra-simple controls make each game easy to get into...until the games start coming faster... and faster...and FASTER!' FROM games WHERE igdb_id = 1703 ON CONFLICT (game_id, language_code) DO NOTHING;
