INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('snk-vs-capcom-svc-chaos', 6184, '2003-07-24', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ydh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fu3g4ar3dusoa9uooga8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SNK vs. Capcom: SVC Chaos', 'SNK vs. Capcom: SVC Chaos primarily utilizes the command system of The King of Fighters series, incorporating light/strong kicks, punches, cancels and charging attacks. Unlike its predecessor, Capcom vs. SNK 2, this game lacks both air guards and a "groove system", instead focusing on quicker gameplay. Characters are provided with a basic 3-level bar system for executing super-special attacks with basic filling options attributed to strikes and damage. Additionally, the sprites from the various series received new models and some special effects were changed in the command lists (for example, the player cannot increase the damage of the Zujou Sashi used by Choi Bounge by tapping the buttons anymore).' FROM games WHERE igdb_id = 6184 ON CONFLICT (game_id, language_code) DO NOTHING;
