INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man Network Transmission', 'Mega Man Network Transmission, known in Japan as Rockman EXE Transmission (ロックマン エグゼ トランスミッション), is a video game developed by Arika and published by Capcom and ShoPro Entertainment for the Nintendo GameCube console. The game was first released in Japan on 6 March 2003, and in North America and PAL regions the following June. Network Transmission is part of the Mega Man Battle Network series, which originated on the Game Boy Advance (GBA) handheld.' FROM games WHERE igdb_id = 1766 ON CONFLICT (game_id, language_code) DO NOTHING;
