INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atv-quad-power-racing-2-ecf4e085-b0ea-46f9-bd0b-d624ee1b4cca', 4173, '2003-01-14', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/p6uxax4h9ocj0hjsepas.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ATV Quad Power Racing 2', 'ATV Quad Power Racing is the sequel to ATV Quad Power Racing on the Playstation, with many new features: Choose from 10 of the top professional riders from all over the world, including Dana Creech, Kory Ellis and Tim Farr. Race through 17 massive tracks and five environments, located in challenging countries throughout the world. Get dirty and physically fight with opponents to the finish line, letting them know that you''re king off-road. Over-the-top controls and game physics, allowing players to pull huge air and amazingly fun power slides. More than 20 freestyle tricks to let riders express their wild side while tearing up the competition. Several multi-player modes of play, brings the action to players and their friends. Real-life in-game sponsors, adding to the realism of the game.' FROM games WHERE igdb_id = 4173 ON CONFLICT (game_id, language_code) DO NOTHING;
