INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Looney Tunes: Back in Action', 'Looney Tunes Back In Action is a hilarious adventure featuring everyone''s favorite cartoon two-some, Bugs Bunny and Daffy Duck, in a globetrotting scavenger hunt to find the mythical Blue Monkey Diamond. From Hollywood to Las Vegas, from Paris to Africa, our roving heroes must run, jump, slide, and bounce their way through a heap of cartoon perils and put an end to the sinister plans of the evil ACME Corporation in an effort to save the world.' FROM games WHERE igdb_id = 3979 ON CONFLICT (game_id, language_code) DO NOTHING;
