INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amped 2', 'Amped 2 is the ultimate freestyle experience, offering the largest, most varied trick library of any snowboarding game. Explore vast areas of wide-open, spectacularly rendered real mountains packed with terrain parks designed by world-famous snow park architect, Chris Gunnarson. Play head-to-head with friends in the various multiplayer modes. When you''re ready to take it to the next level, connect to Xbox Live to check rankings and challenge the world''s best virtual riders.' FROM games WHERE igdb_id = 5725 ON CONFLICT (game_id, language_code) DO NOTHING;
