INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-Zero GX', 'F-Zero GX is the fourth installment in the F-Zero series and the successor to F-Zero X. The game continues the series'' difficult, high-speed racing style, retaining the basic gameplay and control system from the Nintendo 64 title. A heavy emphasis is placed on track memorization and reflexes, which aids in completing the title. GX introduces a "Story Mode" element, where the player walks in the footsteps of Captain Falcon through nine chapters, completing various missions.' FROM games WHERE igdb_id = 3492 ON CONFLICT (game_id, language_code) DO NOTHING;
