INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s 101 Dalmatians II: Patch''s London Adventure', 'Disney''s 101 Dalmatians II: Patch''s London Adventure is a single-player game in which you play as Patch, a Dalmatian puppy who wants to be more than just "one of the 101." Patch''s goal is to find and ultimately save his Dalmatian puppy brothers and sisters, who have fallen into the clutches of the dastardly Cruella De Vil.' FROM games WHERE igdb_id = 43737 ON CONFLICT (game_id, language_code) DO NOTHING;
