INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medal of Honor: Rising Sun', 'First-person shooter set in the Pacific theatre of WWII, beginning with the attack on Pearl Harbor and moving through the campaign with you playing as a young recruit chosen for various historical missions such as the raid on Guadalcanal. The game also makes efforts to educate players in WWII history and conditions, with period stock footage and images, and unlockable interviews with Pacific veterans.' FROM games WHERE igdb_id = 1316 ON CONFLICT (game_id, language_code) DO NOTHING;
