INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arsenal Club Football', 'Club Football is a soccer series designed to re-create the individual team experience. A total of 17 games released in the Club Football series are tailored to the specific European teams on which they are based, including character facial mapping from each of the 22 position players on the roster. Each game features bespoke content - including media archive clips of great goals and famous victories - and allows fans to add themselves to the 2003/04 starting line-up of their favourite side.' FROM games WHERE igdb_id = 22246 ON CONFLICT (game_id, language_code) DO NOTHING;
