INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sphinx and the Cursed Mummy', 'Sphinx and The Cursed Mummy is an original 3rd person action-adventure inspired by the mythology of ancient Egypt. Travelling the world via magical portals to foil the evil plans of Set. Sphinx''s Journey will require all his wits, agility, and special powers. He will also rely on his reluctant hero friend, The Mummy, to help when being inconspicuous is the only solution. By finding the stolen magical crowns of Egypt, Sphinx can stop Set and save the world.' FROM games WHERE igdb_id = 4164 ON CONFLICT (game_id, language_code) DO NOTHING;
