INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('e-dot-t-the-extra-terrestrial-interplanetary-mission', 44985, '2003-01-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co94ro.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scizn7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'E.T.: The Extra-Terrestrial - Interplanetary Mission', 'E.T. may have left Earth safely onboard his spaceship, but trouble awaits him soon after landing in this 3D PlayStation adventure. The universe is in danger and only E.T. can help save it, by finding exotic plants. As the kind-hearted alien from the 1982 film, re-released in 2002 to commemorate its 20th anniversary, players must rescue rare plants from a total of five planets: Green Planet, Ice Planet, Desert Planet, Planet Metropolis, and Earth. Each planet contains a specific number of plants to find across three levels. Worlds are also filled with hostile creatures or government agents, so E.T. needs to use his special powers to help him overcome all manner of threats. As E.T. walks and runs across the levels, he can call upon the power of telekinesis to move items closer, use his healing power to restore flowers, and unleash a heart stun to temporarily freeze enemies. Also available on each level are items such as keys or switches, which let E.T. access blocked areas. Progress in the adventure can be saved to a memory card.' FROM games WHERE igdb_id = 44985 ON CONFLICT (game_id, language_code) DO NOTHING;
