INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Broken Sword: The Sleeping Dragon', 'Broken Sword: The Sleeping Dragon moves away from the 2D point-and-click concept from the earlier games and features a full 3D world, with a camera that does not rotate, but uses fixed cinematic perspectives, combined with full 5.1 sound. For the Windows version the game is no longer controlled through the mouse, but now through the keyboard, for the movement of the characters as well as all the actions. The player alternately controls George or Nico. Next to typical adventure gameplay such as exploration, conversations, and searching and combining items, there are also a few action sequences. The characters can duck, sneak, hang from ledges and move crates to reach higher areas.' FROM games WHERE igdb_id = 1151 ON CONFLICT (game_id, language_code) DO NOTHING;
