INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('war-of-the-monsters', 3208, '2003-01-14', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mtz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/dutueeu2fik028fmtkwz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War of the Monsters', 'Get ready to embody the soul of a 100-foot tall monstrosity as you clash with opponents in thriving cities, run rampant through bustling streets, pulverize opponents with body slams and fight off military defenses. War of the Monsters enables you to re-live your favorite monster movies with ten different creatures engaging in all out carnage. Ten fully interactive environments offer numerous weapons, including steel girders, radio antenna, moving vehicles, building rubble, army tanks and more. Clobber opponents with thunderous uppercuts, hand-to-hand weapons and destructive special attacks. Use huge hunks of debris as a shield, topple buildings onto your foes or pick up and throw tanker trucks like toys. Take advantage of environmental attacks such as tidal waves and earthquakes to defeat your opponent and claim total domination.' FROM games WHERE igdb_id = 3208 ON CONFLICT (game_id, language_code) DO NOTHING;
