INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Pinball Party', 'It''s time to get the party started right with "Sonic Pinball Party" for the Game Boy Advance. Sonic The Hedgehog returns to the Game Boy Advance, with the ultimate handheld pinball experience, delivering fresh pinball boards filled with SONICTEAM characters and a huge assortment of multiplayer party games. With SONICTEAM characters from "Sonic The Hedgehog," "Samba de Amigo" and "Nights," "Sonic Pinball Party" challenges players to shoot, tilt, and flip their way through a slew of pinball boards, lightning fast mini-games and party games that promise to give gamers the pinball fix they''ve been craving!' FROM games WHERE igdb_id = 6601 ON CONFLICT (game_id, language_code) DO NOTHING;
