INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nancy Drew: The Haunted Carousel', 'You, as Nancy Drew, have just entered a tightening circle of fear and crime as you explore a seaside amusement park that’s swirling with secrets. An antique carousel horse as been stolen! Now, late at night, the merry-go-round takes off on bizarre riderless journeys to nowhere. Are the painted ponies searching for their missing lead horse, or is there another explanation for the midnight rides? Take a spin with danger to unravel the mystery of a ghostly carousel!' FROM games WHERE igdb_id = 10586 ON CONFLICT (game_id, language_code) DO NOTHING;
