INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('praetorians', 9058, '2003-02-28', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rsk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar171i.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Praetorians', 'Your destiny awaits you on the battlefield. As a Roman General on a quest to forge an empire, you will be transported back to the dusty battlefields of Egypt, the frozen lands of the Gauls, and finally to the heart of the Empire itself, Italy. Your quest will be no easy task as the lands you seek to conquer are heavily defended by thousands of powerful troops. Feed you insatiable hunger to rule the empire with this combat-heavy epic adventure Command the forces of 3 civilizations - the disciplined Romans, the ferocious Gauls, and the religiously fanatical Egyptians Different landscapes play an all-important role in battle. From snow-capped mountains to sandy beaches, the AI will understand varying terrain and its defensive and offensive possibilities Battle for supremacy online in an intense multiplayer match supporting up to 8 players Master the art of war in over 20 single player missions requiring vastly different strategies' FROM games WHERE igdb_id = 9058 ON CONFLICT (game_id, language_code) DO NOTHING;
