INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Piglet''s Big Game', 'It is another blustery day in the Hundred Acre Wood and Pooh, Tigger, Roo, Rabbit, Owl and Eeyore are having bad dreams of Heffalumps and Woozles. Pooh dreams that his honey is gone. Rabbit dreams his harvesting machine is broken. Roo dreams his ball is stuck in a tree. And Eeyore has lost the colors in his dreams. In this fun-filled adventure in dreams it is up to Piglet to save the day by being the bravest Piglet of all!' FROM games WHERE igdb_id = 4066 ON CONFLICT (game_id, language_code) DO NOTHING;
