INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uru: Ages Beyond Myst', 'From the makers of Myst and Riven comes the next chapter of the Myst franchise. In Uru: Ages Beyond Myst, you''ll journey through a variety of different ages and discover the lost civilization of the D''ni people. This time, you don''t have to point and click to move around--you can explore each age in real-time 3D. Create your own character and spend hours discovering mysterious areas, solving a large variety of mind-challenging puzzles, and following an epic storyline.' FROM games WHERE igdb_id = 50395 ON CONFLICT (game_id, language_code) DO NOTHING;
