INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nancy Drew: Danger on Deception Island', 'A much-anticipated vacation to a remote island in the Pacific Northwest abruptly runs aground when you, as Nancy Drew, discover that an unseen assailant has vandalized the whale-watching boat owned by your host, Katie Firestone. But that’s just the first in a string of nasty “accidents.” Is the brought in Snake Horse Harbor related to the orphaned orca whale roaming the nearby channel, or is there a deeper threat shrouded in the approaching fog? Plunge into danger to bring a mysterious island’s secrets to the surface! Dare to Play.' FROM games WHERE igdb_id = 10580 ON CONFLICT (game_id, language_code) DO NOTHING;
