INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deus Ex: Invisible War', 'Several religious and political factions see an opportunity to re-shape a worldwide government to their agendas. In this techno-nightmare, take part in the dark struggle to raise the world from its own ashes. This dynamic and innovative 1st person-action/adventure brings a level of reality unprecedented in a videogame. Biotech modifications allow players to see through walls, leap 40 feet into the air, regenerate critical body damage or render yourself radar invisible. Globe-hop to real world locations such as Seattle, Antarctica, and Cairo.' FROM games WHERE igdb_id = 42 ON CONFLICT (game_id, language_code) DO NOTHING;
