INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('growlanser-iv-wayfarer-of-the-time', 21313, '2003-12-18', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2no3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm69e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Growlanser IV: Wayfarer of the Time', 'Growlanser IV: Wayfarer of Time is a mix between a real-time and turn-based strategy RPG that was released on the PlayStation 2 in Japan on December 18, 2003. The title was the fourth entry in the Growlanser series and was the last entry to use 2D sprites before transitioning to 3D with the next installment. An enhanced port for the PlayStation Portable was released in Japan on August 18, 2011 under the title Growlanser IV: Over Reloaded, which featured a new animated opening as well as several new story paths, characters and other gameplay improvements. Atlus USA localized the PSP port as Growlanser: Wayfarer of Time and released it in North America on July 31, 2012. Never before released outside of Japan and widely considered the best entry in the long-running franchise, this PSP system iteration of the fourth chapter in the Growlanser saga delivers visuals remastered for PSP system''s 16:9 widescreen, a vastly expanded script with tons of new characters to meet and quests to complete, a wealth of new ending possibilities, and much more, making it the first and only version of the game North American fans will ever want!' FROM games WHERE igdb_id = 21313 ON CONFLICT (game_id, language_code) DO NOTHING;
