INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors 4: Xtreme Legends', 'Dynasty Warriors 4: Xtreme Legends includes all 42 characters from the original Dynasty Warriors 4, with new gameplay elements. Engage in randomly generated skirmishes in Xtreme Mode. Live the exploits of all warriors in Legends Mode. Experience endurance-style duels in the Arena Challenge. Play it by itself or in conjunction with the original using Xtreme Legends'' disc swap feature. Here''s your chance to become a legend among legends.' FROM games WHERE igdb_id = 19631 ON CONFLICT (game_id, language_code) DO NOTHING;
