INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Goblin Commander: Unleash the Horde', 'Set in a fantasy world, the story follows the tale of a civil war between goblin clans after their creator and master is killed. The gameplay is a combination of real-time strategy and light action where players gather resources and build up their horde of goblins while also being able to take direct control of certain units.' FROM games WHERE igdb_id = 3934 ON CONFLICT (game_id, language_code) DO NOTHING;
