INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('starsky-hutch', 4183, '2003-06-20', 64, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p1k.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starsky & Hutch', 'Starsky & Hutch is an arcade racing game based on the popular TV series from the 70s, released to tie in with the film. The game includes 18 missions, each based on an episode of the TV show and introduced by Antonio ''Huggy Bear'' Fargas. There is also a free roaming mode, in which the player explores the GTA-esque environment looking for action and trouble. Like the film, the game does not entirely play it straight. Starsky & Hutch are actually shooting a TV show, and the scoring for each mission reflects how ratings-friendly your driving is. You are awarded gold, silver or bronze medals for each mission depending on performance, and must get at least 1 gold and 2 silvers on season 1 for a second season to be commissioned, and 3 golds and 2 silvers in season 2 for there to be a third for you to play through. The overall goal in each mission is usually to chase and destroy a criminal''s car. There is always a secondary target as well. In addition, the player will gain viewers by hitting the bad guy, pulling off elaborate jumps and skids, nearly hitting civilians, and hitting the bonus targets such as canisters which are strewn through the levels. Hitting civilians will lose viewers.' FROM games WHERE igdb_id = 4183 ON CONFLICT (game_id, language_code) DO NOTHING;
