INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wakeboarding-unleashed-featuring-shaun-murray', 23694, '2003-06-03', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1onw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmlfn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wakeboarding Unleashed Featuring Shaun Murray', 'Wakeboarding is part of Activision''s line of Extreme Sports titles. A rider (using a board that''s like a combination of a surf board, body board and skateboard) is pulled along the water by rope at high speeds by the boat up front, and must pull of tricks either by jumping of jumps or using the wake left by the boat itself (hence the sport''s name). Unleashed takes this sport and turns it upside down, allowing you to fly down water ways through well known locations around the world, pulling stunts off buildings or cliff faces. Other objectives are included that have you completing tasks and busting tricks in a unique way. Multiplayer modes include one-on-one trick attack and horse, where both players compete against each other to pull off the best tricks. Co-operative mode has one player driving the boat while the other hangs on behind, with new challenges for the boat driver to complete as well as the rider.' FROM games WHERE igdb_id = 23694 ON CONFLICT (game_id, language_code) DO NOTHING;
