INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil May Cry 2', 'Devil May Cry 2 is the sequel to Devil May Cry. From the start of the game, the player controls Dante or his new partner Lucia through various levels as they battle waves of demons. This game features an Amulet system, with different parts being acquired throughout the levels that can be equipped by accessing the pause menu. The different parts of the amulet can be equipped to change aspects of the characters Devil Triggers form like elemental moves, time stop abilities, faster movement, flight abilities, etc.' FROM games WHERE igdb_id = 135 ON CONFLICT (game_id, language_code) DO NOTHING;
