INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lethal-skies-ii', 24103, '2003-09-09', 81, 'https://images.igdb.com/igdb/image/upload/t_cover_big/y3hr1nc51mtj9n12w2u7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wmipibjysvrjmaqj0mfz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lethal Skies II', 'A year-long global war between the World Alliance and the World Order Reorganization Front has ended with planet Earth in peril. As a result of resentment and distrust, the World Alliance has begun to split and the seeds for a new global war are being planted. Nowhere is safe, not even the skies. Pick-up and play arcade-style flight shooter, with varying degrees of difficulty for casual and hardcore flight combat fans. Seven new fighter jets for a total of 19 playable planes, including modern-day combat jets, classified "black ops" planes and futuristic fighters. Over 20 missions that put the player in command of an Air Force amidst an epic war, with unlockable campaigns that let players switch roles and become the enemy. Amazing new features, including split-screen and i.Link 2-player mode, fully interactive 3D battle maps, movie galleries and five different 1st and 3rd person point of views.' FROM games WHERE igdb_id = 24103 ON CONFLICT (game_id, language_code) DO NOTHING;
