INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-simpsons-hit-run', 2844, '2003-09-16', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2uk7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7e2v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons: Hit & Run', 'Strange wasp-shaped spy cameras, shady black vans lingering about, and a brand new flavor of Buzz Cola that everyone seems a bit too excited about. What could it all mean? Find out as you take to the streets as America''s most beloved dysfunctional animated family: The Simpsons! In this timeless action-adventure game, you can work to uncover the conspiracy taking place in Springfield while playing as these beloved characters. As you progress through the game, you''ll explore 3 unique areas of Springfield made up of many locations from the show. You can ride around in style with a memorable array of vehicles from the show or take a walk around on foot. You''ll stumble into adrenaline-pumping story missions, take part in some fast paced street races and help out some of the townsfolk in bonus missions. Around every corner there''s pesky wasps to be destroyed, collector cards to find and secret gags to uncover.' FROM games WHERE igdb_id = 2844 ON CONFLICT (game_id, language_code) DO NOTHING;
