INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem', 'It is the seventh game of the Fire Emblem series, the second game in the series to be released for the Game Boy Advance, and the first to be released in both North America and Europe. It features a prologue storyline designed to introduce newcomers to Fire Emblem gameplay and tactical basics. The overall narrative is a prequel to the events of the previous game, Fire Emblem: The Binding Blade, which is set twenty years later. The game was first released under the localized title "Fire Emblem" in the West, but it was later rebranded as "Fire Emblem: The Blazing Blade" when Fire Emblem Heroes was released.' FROM games WHERE igdb_id = 1439 ON CONFLICT (game_id, language_code) DO NOTHING;
