INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Golf: Toadstool Tour', 'Hit the links in the Mushroom Kingdom! Mario, Peach, Yoshi, Donkey Kong and others have tee times reserved in the Mushroom Kingdom! Challenge them to tournaments, or take them on in character matches to collect rings or nab coins! Play on resort-style courses or look out for Chain Chomps, Warp Pipes and Thwomps on the Mushroom Kingdom courses!' FROM games WHERE igdb_id = 3403 ON CONFLICT (game_id, language_code) DO NOTHING;
