INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wallace and Gromit in Project Zoo', 'Wallace & Gromit in Project Zoo is a platform video game developed by Frontier Developments and published by BAM! Entertainment (European distribution being handled by Acclaim Entertainment) for the PlayStation 2, GameCube, Xbox and Microsoft Windows. It is the first console game to feature Aardman Animations'' characters Wallace & Gromit and also features the voice of Wallace, Peter Sallis reprising his role.' FROM games WHERE igdb_id = 2728 ON CONFLICT (game_id, language_code) DO NOTHING;
