INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dungeons-dragons-heroes', 5819, '2003-09-16', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5x5f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5kzc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons & Dragons: Heroes', 'Journey through a world filled with magic and monsters, treasures and traps, good and evil--a world unto itself where heroes are made not born. Take on perilous quests through never-before-seen planes of existence and carve a path to righteousness. Conquer dungeons, search for gemstones, fight monsters, improve your skills and more as one of four distinct Hero characters: Fighter, Wizard, Cleric or Thief. Immediately immerse yourself in solo games or play cooperatively with up to 4 players. Dungeons & Dragons: Heroes gives you a chance to taste victory as only a true Hero can.' FROM games WHERE igdb_id = 5819 ON CONFLICT (game_id, language_code) DO NOTHING;
