INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Heroes', 'Sonic Heroes is an adventure and multiplatform video game in the Sonic The Hedgehog series, developed by Sonic Team and published by SEGA for the Nintendo GameCube, Sony PlayStation 2, Microsoft Xbox and Microsoft Windows PCs. The player races a team of series characters through levels to amass rings, defeat robots, and collect the seven Chaos Emeralds needed to defeat Doctor Eggman. This game differs from other Sonic games by allowing the player to take control of one of four teams, each with three characters, who each have unique abilities to use. The game received mixed reviews from critics but it performed commercially well, becoming a million-seller and making the best-selling lists for all three of its original platforms. Join Team Sonic, Team Dark, Team Rose and Team Chaotix in a multiplatform adventure! Run, Fly, use your Power, grind, swing through 7 different levels with unique paths, fighting evil and solving puzzles for each team.' FROM games WHERE igdb_id = 4156 ON CONFLICT (game_id, language_code) DO NOTHING;
