INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'P.N.03', 'A colonial settlement on a distant planet goes out-of-control after a Computer Arms Management System goes haywire. Enter Vanessa Schneider, a freelance mercenary and robot killer with a grudge to settle in this exhilarating action game. But will Vanessa''s dark past collide with her ultimate mission?' FROM games WHERE igdb_id = 4060 ON CONFLICT (game_id, language_code) DO NOTHING;
