INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster 4x4: Masters of Metal', 'Get ready to pilot the world''s most powerful trucks and go head-to-head in pulse-pounding off-road competitions. You can pick from over 20 unstoppable Monster trucks, including Grave Digger, El Toro Loco, Bulldozer, Bounty Hunter, Blue Thunder, and Maximum Destruction. Whether you''re grinding through mud pits in Louisiana, crunching up cliffs in California, or smashing up trees to make the ride a little bumpier for the guy behind you, keep your eyes on the prize: The cash you earn on the circuit goes to buy new trucks and build up your ultimate Monster machine.' FROM games WHERE igdb_id = 4017 ON CONFLICT (game_id, language_code) DO NOTHING;
