INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('heaven-and-hell', 50406, '2003-09-15', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/i7vvsznfbvcacxfqfa0j.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heaven & Hell', '...And lead us not into temptation - But that''s the whole point! Indulge yourself. Take on the amusing role of a soul snatcher who wields omniscient power.  Play Heaven & Hell: convince the cute and cuddly Earth dwellers that you''re the long-awaited Redeemer who''ll bring salvation to their chaotic world. Let no one doubt the truthfulness of your message. Your faithful fanatics launch rotten fruits and vegetables at opposing prophets, while your prophets pummel doubters into holy submission. Alternatively, use miracles and plagues to lead the disbelieving unto the path of the righteous. In this way, your flock shall grow and grow and grow...' FROM games WHERE igdb_id = 50406 ON CONFLICT (game_id, language_code) DO NOTHING;
