INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Reshef of Destruction', 'In your return to Battle City, you begin another mission to retrieve stolen millennium cards that can destroy the world. Yu-Gi-Oh! Reshef of Destruction features an all-new storyline that sets you off on a quest to stop Reshef from drowning the world in darkness. Since the game''s battles are fought with cards, you must build a strong deck from 800 different cards (including all three Egyptian god cards) to even stand a chance against your enemies.' FROM games WHERE igdb_id = 49379 ON CONFLICT (game_id, language_code) DO NOTHING;
