INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Park: Operation Genesis', 'Jurassic Park: Operation Genesis (often abbreviated JP:OG or simply JPOG) is a park-building game that allows players to create their own version of Jurassic Park. It is reminiscent of games like SimCity and Zoo Tycoon. Parks can earn stars by entertaining visitors. As a players park earns stars, the park will become more popular. The more stars and popularity, the more visitors players will have. It is one of the more popular Jurassic Park games to be released.' FROM games WHERE igdb_id = 5871 ON CONFLICT (game_id, language_code) DO NOTHING;
