INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legacy of Kain: Defiance', 'Legacy of Kain: Defiance is an action-adventure game developed by Crystal Dynamics and released in 2003. It is the fifth entry in the Legacy of Kain series and continues the intertwined stories of Kain and Raziel. Players alternate between controlling the two protagonists, each with distinct abilities and combat styles. The game combines exploration, puzzle-solving, and fast-paced melee combat in a gothic fantasy setting.' FROM games WHERE igdb_id = 5901 ON CONFLICT (game_id, language_code) DO NOTHING;
