INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bujingai: The Forsaken City', 'An isolated island-city stands as home to much of what remains of the human race. The ancient technology which annihilated most of the earth has now opened a gateway to a hellish dimension, unleashing a horde of demons upon the city. One warrior, armed with a pair of swords and an arsenal of magic spells, goes to battle the army of demons. This warrior''s name is Lau, and thousands will die by his hand.' FROM games WHERE igdb_id = 19413 ON CONFLICT (game_id, language_code) DO NOTHING;
