INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SOCOM II: U.S. Navy SEALs', 'SOCOM II is a third-person tactical shooter. There are 12 different single-player missions: split equally between Albania, Algeria, Brazil and Russia. There are five different ranks that can be played in the game: Ensign, Lieutenant, Commander, Captain and Admiral. The player starts with the first three ranks unlocked, but must finish the single player game on Commander to unlock Captain, and on Captain to unlock Admiral. Players can unlock new models for multiplayer, as well as movies, music, concept art, and credits by completing certain objectives.' FROM games WHERE igdb_id = 8240 ON CONFLICT (game_id, language_code) DO NOTHING;
