INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon: A Wonderful Life', 'Harvest Moon: A Wonderful Life will span a lifetime on the farm and follow the drama that goes with it. Not only must you build and successfully run a farm, but you must also build a successful life with family and friends! This new Harvest Moon experience will take the best qualities of the series and add more...more animals, more vegetables and more drama! What sort of life will you live?' FROM games WHERE igdb_id = 3384 ON CONFLICT (game_id, language_code) DO NOTHING;
