INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Casino Inc', 'Classic strategy game from 2003. Run your own casino in the 1970s. It''s classy. It''s glitzy. It''s all yours. Take a gamble. Start small with a slot machine or two. Employ some staff. People will be talking about your place from coast to coast. Includes The Management Expansion Pack.' FROM games WHERE igdb_id = 35438 ON CONFLICT (game_id, language_code) DO NOTHING;
