INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby Air Ride', 'Kirby Air Ride is a 2003 racing game video game developed by HAL Laboratory and published by Nintendo for the Nintendo GameCube video game console. The game has the players and computer-controlled racers ride on Air Ride Machines. The game supports up to four players, and was the first GameCube title to support LAN play using broadband adapters and up to four GameCube systems. Players take control of Kirby or any of his multicolored counterparts to compete in races or other minigames. The game consists of three different game modes: Air Ride, Top Ride, and City Trial.' FROM games WHERE igdb_id = 2777 ON CONFLICT (game_id, language_code) DO NOTHING;
