INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Insaniquarium! Deluxe', 'Dive into wild arcade action as you feed fish and fight aliens in the craziest aquarium around! Control and protect a colorful aquarium with fantastic fish and colorful sea creatures by keeping your friendly fish fed and happy... and safe from alien intruders! Feed your fish, then quickly collect the coins they drop to upgrade to better food, amazing new fish species and awesome weapons. But make sure to use those weapons on all the ruthless extraterrestrial boss beasts, or you''ll be sunk in an empty tank!' FROM games WHERE igdb_id = 8323 ON CONFLICT (game_id, language_code) DO NOTHING;
