INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-tale-in-the-desert', 23701, '2003-02-15', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yqg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc99vj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Tale in the Desert', 'A Tale in the Desert is a Massive Multiplayer Online Roleplaying Game (MMO), presented by Desert Nomad Studios, and set in ancient Egypt. The game focuses on crafting and trading, mixed with strong social and political challenges, and has absolutely no combat. Within the game is one of the most complex crafting and trade skill systems that have ever been created. This is coupled with tests in various disciplines that challenge players to work together or against each other. Be creative in the arts or build massive structures, create complex thought puzzles to challenge other players. The game is a great sociological experiment, asking questions like "Will players work together in a project when working against each other could potentially have more benefit to one of them?".' FROM games WHERE igdb_id = 23701 ON CONFLICT (game_id, language_code) DO NOTHING;
