INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Princess Maker Refine', 'Princess Maker Refine revisits the classic first installment of the Princess Maker series, a mainstay of the simulation gaming genre with a long-lasting and dedicated fan base. Princess Maker combines simulation gaming with an interesting, in-depth story as it follows the tale of a young girl adopted by a warrior and raised to become a lady.' FROM games WHERE igdb_id = 27317 ON CONFLICT (game_id, language_code) DO NOTHING;
