INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Knights of the Old Republic', 'Choose Your Path! Set 4,000 years before the Galactic Empire, you are the last hope for the Jedi Order and the Republic - can you master the ways of the Force to become their savior? Or will you fall to the dark side and achieve ultimate power? Hero, villain, peacekeeper, or chaos-bringer... you and your party will determine the fate of the galaxy! Star Wars: Knights of the Old Republic is a role-playing video game. Players will be able to create their own characters and be able to choose what gender, appearance, class, skills, attributes, and feats they have throughout the game - no two characters will be the same!' FROM games WHERE igdb_id = 116 ON CONFLICT (game_id, language_code) DO NOTHING;
