INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlestar Galactica', 'The war between man and machine rages on as the mechanical Cylons return to wipe out the human race. Begin your heroic journey through the Battlestar Galactica universe as the fearless, young Adama, and help lead the fleet of Colonials to survival. Choose from a wide array of ships, from sleek Vipers to heavy Bombers, and engage various classes of Cylon vessels, including Raiders and Marauders.' FROM games WHERE igdb_id = 5744 ON CONFLICT (game_id, language_code) DO NOTHING;
