INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nascar-racing-2003-season', 804, '2003-02-13', 100, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2idh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/x5worctez0jp0bzrqx5e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR Racing 2003 Season', 'The latest release from this series since 1999. 23 real-life tracks (including the new versions of New Hampshire International Speedway and Infineon Raceway) are included. The game has been reworked with an improved graphics and physics engine, developed in partnership with Goodyear Tire & Rubber Company and Jasper Motorsports. Tutorials will bring the player up to speed quickly, while driving aids will help them compete against NASCAR pros. An adaptive AI will keep the game challenging at all skill levels. Multiplayer supports up to 42 players online in the same race.' FROM games WHERE igdb_id = 804 ON CONFLICT (game_id, language_code) DO NOTHING;
