INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Club II', 'Midnight Club II is a racing video game developed and published by Rockstar San Diego (formerly Angel Studios). It is the first sequel to Midnight Club: Street Racing, published for the PlayStation 2, Xbox and Microsoft Windows. Players can race through cities based on Los Angeles, Paris, and Tokyo. The game also features an online multiplayer component. It is the second game in Midnight Club franchise, followed by Midnight Club 3: DUB Edition.' FROM games WHERE igdb_id = 4631 ON CONFLICT (game_id, language_code) DO NOTHING;
