INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('summer-heat-beach-volleyball', 22242, '2003-07-30', 71, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p1y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sciyo1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Summer Heat Beach Volleyball', 'Following in the same vein as Dead Or Alive: Xtreme Beach Volleyball, hot girls in bikini''s playing beach volleyball comes to the Playstation 2 in the form of Summer Heat Beach Volleyball. The game features both male and female competitors from around the world and follows the rules of 2 on 2 volleyball. Unlike Beach Spikers you only control one player on your team, the other player is controlled by the game, unless you play a 2-player co-operative game. There are 12 different locations in the game and 14 playable characters, each with their own statistics. The game features Arcade, Exhibition, Summer Heat US Tour and Training modes. As you progress thorugh the different modes, you unlock items of clothing, music videos, courts and more. There are also mini-games to be played. You can also relax at the Beach House were you can watch videos, listen to music and check out your trophies.' FROM games WHERE igdb_id = 22242 ON CONFLICT (game_id, language_code) DO NOTHING;
