INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kill-dot-switch', 5881, '2003-10-28', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57c7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6snh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kill.Switch', 'Aiming and moving in cover and blind-fire modes is tricky, though. To gain the 3-D effect, some detail gets sacrificed. Usually this is no problem, but occasionally you''ll have a tough time recognizing an object. You move from area to area to engage a new group of enemies. You''ll conveniently find crates for cover and barrels to help you pull off big explosions. Locking the enemy in your crosshairs, signified by your crosshairs turning red, doesn''t guarantee a direct hit? The accuracy depends on the weapon of choice. A shotgun will normally provide a kill on the first shot. If you have an automatic rifle, your shots are relatively inaccurate even if your aim is true.' FROM games WHERE igdb_id = 5881 ON CONFLICT (game_id, language_code) DO NOTHING;
