INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('action-replay-max', 43302, '2003-09-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3i3s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scbzg4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Action Replay Max', 'Action Replay MAX is the most powerful PS2 game enhancer ever made. It’s packed with cheats and enhancements for your favourite games, lets you play import DVD''s on your local PS2, and can be updated over the internet or by typing in new codes. The world''s most powerful cheat code system and video game enhancer is now better than ever before! Action Replay MAX once again takes PlayStation 2 game enhancement to a higher level. Action Replay MAX is packed with game-busting codes, allowing you to beat your PS2 games with a whole host of 100% unofficial cheats you won''t find anywhere else. Instantly acquire MAX health, ammo and money. Unlock secret characters, levels, vehicles and much, much more.' FROM games WHERE igdb_id = 43302 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 43302 AND p.igdb_id = 8 ON CONFLICT DO NOTHING;
