INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fenimore-fillmore-the-westerner', 27496, '2003-12-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ai2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arl3x.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fenimore Fillmore: The Westerner', 'Take on the role of Fenimore Fillmore as you confront the evil John Starek, who has been threatening the local townspeople into selling him their land. In this wild adventure, you''ll meet more than 30 different characters, collect useful inventory objects, and encounter an array of Wild West situations. Ride the rails, fight in barroom brawls, or choose to take it outside in a deadly gunfight. The choice is yours. If you help the townspeople fight to keep their land, you just might be able to ride off into the sunset with the girl of your dreams.' FROM games WHERE igdb_id = 27496 ON CONFLICT (game_id, language_code) DO NOTHING;
