INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DreamMix TV World Fighters', 'A fledgling television program has been suffering from poor audience approval, and the station that carries the show has informed its producers that they will have to rectify the situation or face inevitable cancellation. An unorthodox plan is implemented: broadcast a contest pitting various superstars from differing realities in physical combat in order to increase ratings.' FROM games WHERE igdb_id = 3899 ON CONFLICT (game_id, language_code) DO NOTHING;
