INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('freedom-fighters', 719, '2003-09-26', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coar05.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arugp.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freedom Fighters', 'Freedom Fighters is a third-person shooter, in which the player navigates through the streets of New York while fighting the Soviet forces. The game also contains squad-based elements, having a charisma meter. The player gains charisma by performing heroic deeds in the resistance movement against the invading forces, like capturing a base or destroying vital supplies. The more charisma that is gained, the more squad-mates the character can recruit, including leaderless guerrillas and wounded Russian soldiers, up to a maximum of twelve. Freedom Fighters uses a simple method of controlling recruits in battle. In the game, the player can command recruits by giving them simple orders such as "follow", "attack" and "defend", but in most situations, they take care of themselves. Given the terrain of New York City after the initial invasion, the Resistance usually stations its soldiers in covered positions like craters and buildings.' FROM games WHERE igdb_id = 719 ON CONFLICT (game_id, language_code) DO NOTHING;
