INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('asterix-and-obelix-kick-buttix', 3789, '2003-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5fay.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scj6mw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asterix & Obelix: Kick Buttix', 'Asterix & Obelix: Kick Buttix is an action platformer starring Asterix and Obelix on a mission to save their captured friends from the Roman Empire. The gameplay consists of the ability to switch between Asterix and Obelix at different times, using each one''s skills to your advantage. Through the adventure, you will unlock and gain powerful combos and attack moves. This large adventure takes you through six different countries made up of 47 areas, totaling 40 plus levels. The gameplay is varied from battling hundreds of Romans at once to riding/racing sequences and puzzle-solving. The graphics have vibrant colors, picturesque backgrounds, exciting special effects, and humorous animations. The sound includes zany effects, a range of music from roman to Egyptian, and good-humored voice acting.' FROM games WHERE igdb_id = 3789 ON CONFLICT (game_id, language_code) DO NOTHING;
