INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Colosseum', 'Pokemon fans can now battle their favorite Pokemon on the grand stage. Starring a brand new leading character, Pokemon, Colosseum offers a story mode that pits you against tough trainers who routinely catch damaged Pokemon. In Battle mode, you can use the Game Boy Advance cable to send your team from your Pokemon Ruby or Pokemon Sapphire Game Pak to your Gamecube, then witness the true potential of your team. Rescue Pokemon and watch them come to life in spectacular Colosseum battles.' FROM games WHERE igdb_id = 2725 ON CONFLICT (game_id, language_code) DO NOTHING;
