INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('airline-tycoon-deluxe', 11086, '2003-10-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2abf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5dha.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airline Tycoon Deluxe', 'Airline Tycoon Deluxe is a funny economy simulation proceeding in real-time and assigning you the complete responsibility for an airline. However, don’t be fooled by the funny comic style or the included jokes: A variety of tasks are requested and your competitors never miss a chance to set a trap for you in order to put a spoke in your wheel. Your abilities are put to the test continuously playing Airline Tycoon Deluxe: Will you be able to use your airplanes to capacity and land some profitable charter flights? Can you establish routes for lucrative scheduled flights? Airplanes cost millions; will you be capable of increasing the share price and obtaining enough funds by the issuing of securities? Can you stand up for the construction of new airplanes in your role as an engineer? Are you able to avoid your competitors’ deceitful attacks? Accept this unusual challenge and win virtual laurels with Airline Tycoon. The deluxe version contains 20 new airports as well as new opportunities. It is as interesting for professional tycoons as for beginners.' FROM games WHERE igdb_id = 11086 ON CONFLICT (game_id, language_code) DO NOTHING;
