INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunter: The Reckoning Wayward', 'Evil exists everywhere, but it is unseen by most. As a Hunter, you have the special gift--or curse--to recognize and destroy the evil that has come back from the dead to dwell the earth. This time, an evil cult has formed in Ashcroft and it''s up to Hunters to destroy it. Choose from five playable characters--each with unique weapons, edges, and supernatural abilities--and fight crowds of monstrous enemies. Based on White Wolf''s pen-and-paper role-playing game, Hunter: The Reckoning Wayward combines an intense storyline, deadly characters, and gothic environments.' FROM games WHERE igdb_id = 24096 ON CONFLICT (game_id, language_code) DO NOTHING;
