INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'American Conquest', 'American Conquest: In the year 1492, travel to America as Christopher Columbus and ignite the fire that will fan 300 years of heated battles for land, riches, and freedom. In eight historical campaigns spanning 42 missions, you will take on the roles of great legends such as Francisco Pizarro and George Washington. Secure new technologies, unique weaponry, and improved fighting units, but also master the delicate world of diplomacy. Play with fire! Conquer America.' FROM games WHERE igdb_id = 596 ON CONFLICT (game_id, language_code) DO NOTHING;
