INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpyHunter 2', 'Shift into something more lethal. The hunt begins again with SpyHunter 2. The ultimate high-speed combat thrill ride continues with the world''s most powerful counterintelligence vehicle, the all-new G-B155 Interceptor. Uncover Nostra''s sinister plans for world domination and discover the secrets of a mysterious female agent before it''s too late.' FROM games WHERE igdb_id = 6152 ON CONFLICT (game_id, language_code) DO NOTHING;
