INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Orient Expedition: The Quest for the Golden Dragon', 'An online adventure mini game based on the Adventures: Orient Expedition Lego sets, specifically on the 7419 Dragon Fortress set''s storyline. It was available to play on the Lego.com site at the time of release (2003). It is a puzzle, maze, adventure game, consisting of switching between 3 characters, looking for the artifacts and then reaching the Dragon Fortress Statue with all the characters and artifacts to complete the game.' FROM games WHERE igdb_id = 210319 ON CONFLICT (game_id, language_code) DO NOTHING;
