INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('unreal-ii-the-awakening', 6222, '2003-02-03', 61, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wjl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1706.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unreal II: The Awakening', 'You are John Dalton, an ex-Marine assigned to patrol the edge of human space as a Marshal for the Terran Colonial Authority. Unexpectedly, your monotonous life is shattered by a chilling distress signal, plunging you into an adventure beyond belief. Violent turmoil among the races has erupted on your watch. Thrust into a conflict that will determine the fate of the galaxy, you are humanity''s only hope for salvation. Only you can prevent the Awakening. Not Your Average Mission - Command a team of marines defending a ravaged base. Infiltrate an enemy stronghold. Rescue the trapped survivor of an alien raid. With a demanding array of objectives, you have one overriding goal - survival. Be ready for anything. Unreal Graphics and Sound - Awe-inspiring graphics immerse you in a swarm of alien worlds full of breathtaking scenery and brutal action. 3D sound envelops you in hailstorms of bullets, mind-jarring explosions and the eerie chatter of alien tongues. From Your Mind to the Game - Use the included Unreal Editor software to create your own levels of Unreal play. Design your own game mods and challenge others to enter your personal Unreal Universe. 2003, Epic Games, Inc. All rights reserved. Epic, Epic Games, Unreal, and Unreal II are trademarks or registered trademarks of Epic Games, Inc. in the United States of America and elsewhere.' FROM games WHERE igdb_id = 6222 ON CONFLICT (game_id, language_code) DO NOTHING;
