INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: Underground', 'Need for Speed: Underground is a 2003 racing video game and the seventh installment in the Need for Speed series. It rebooted the franchise, ignoring previous Need for Speed games that featured sports cars and exotics. Underground is the first game in the series to offer a career mode that features a comprehensive storyline, as well as a garage mode that allows players to fully customize their cars with a large variety of brand-name performance and visual upgrades.' FROM games WHERE igdb_id = 96 ON CONFLICT (game_id, language_code) DO NOTHING;
