INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Onimusha: Blade Warriors', 'Onimusha Blade Warriors is a multiplayer fighting game based on the first two games of the Onimusha series. Familiar elements taking from the Onimusha games include the medieval Japanese settings, the characters, items, and the ability to absorb souls in order to perform a magical attack. Fourteen characters are available initially, but a total of twenty-four can be unlocked over the course of play, including long-time Capcom superstars Mega Man and Zero. With the addition of items and weapons strewn around the battle field which characters can pick up to aid in battle, gameplay is aptly compared to one of Capcom''s other fighting franchises, Power Stone.' FROM games WHERE igdb_id = 10551 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 10551 AND ge.slug = 'fighting' ON CONFLICT DO NOTHING;
