INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlowOut', 'As Major John "Dutch" Cane, you''ll lead an elite platoon of mercenary commandos, outfitted with the most deadly experimental weaponry, into the pit of evil. It''s your job to rid the world of mutated beasts and alien insects through 10 levels of intense action. To ensure your team''s success, the military has given you access to a variety of weapons, including a 20mm pump-action shotgun, eight-meter flamethrower, plasma rifle, machine gun, and an eight-inch nailgun. Blast through walls, ceilings, and floors to discover secrets and power-ups that enhance your weapons.' FROM games WHERE igdb_id = 3825 ON CONFLICT (game_id, language_code) DO NOTHING;
