INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Spin', 'Top Spin is the complete tennis experience. Define your tennis playing style, take risks, pull off world-class shots, and work the crowd to develop a unique image on the court. You can also train with a coach, to master shots and playing surfaces and work your way up the online rankings to become the best in the world. Top Spin offers singles or doubles matches with 16 of the world''s top professionals, including cover athletes Anna Kournikova and the world''s number-one player, Lleyton Hewitt.' FROM games WHERE igdb_id = 5234 ON CONFLICT (game_id, language_code) DO NOTHING;
