INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('railroad-tycoon-3', 840, '2003-10-27', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2r3o.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4fe9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Railroad Tycoon 3', 'A fully realised 3D gaming world scaling from eye in the sky views of entire continents down to incredibly detailed close-ups of beautifully modelled locomotives, buildings and landscapes. As well as the 25 challenging scenarios to recreate magnificent feats of railroading history, players can pick from over 40 locomotives over 35 different cargoes and in excess of 150 buildings ? all to be used in a dynamic, fluid economy. Railroad Tycoon 3 defines the essence of tycoon simulations with incredible attention to detail in a living, breathing world, built around a truly amazing game! All aboard.' FROM games WHERE igdb_id = 840 ON CONFLICT (game_id, language_code) DO NOTHING;
