INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('18-wheels-of-steel-across-america', 26814, '2003-09-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6sd1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vkhyoyparcfkalb5aspz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '18 Wheels of Steel: Across America', 'Heed the call of the open road, throw the gears in motion and take off in a tractor trailer. Drive faster than your competition, haul your cargo across the entire United States and feel the wind in your face as you control your own destiny. Blast the horn and build a career in the fast-paced world of trucking. Keep in mind that there''s more to being a successful businessman than just driving fast. You''ve got to manage your money, keep your rig running smooth and watch out for speed traps that might trip you up. Bad weather? Fuel troubles? Tricky loading docks that require pinpoint precision? It''s all part of life in the cab of a 18-wheeler. If you''ve got the guts, jump in a truck and head out for the highway.' FROM games WHERE igdb_id = 26814 ON CONFLICT (game_id, language_code) DO NOTHING;
