INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Voodoo Vince', 'No Pain, No Gain! Vince was just a voodoo doll in a French Quarter shop, but when his maker was kidnapped, he became a vengeful doll on a mission! Using voodoo powers, Vince must kick his own butt to beat his enemies! If he stand under a falling safe, bad guys get flattened! Stick a pitch fork in him, and his enemies are done!' FROM games WHERE igdb_id = 5466 ON CONFLICT (game_id, language_code) DO NOTHING;
