INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('american-conquest-fight-back', 9360, '2003-08-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qlg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfe0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'American Conquest: Fight Back', 'Three centuries of war continue with frantic combat and desperate power struggles raging across the American continent. The Spanish press the attack in the Yucatan against the fierce Maya and Aztec nations. The Germans put all their efforts into finding the legendary El Dorado. The Pontiac Uprising ends in a terrifying bloodbath between Native Americans and the British. And the Russians will do anything to conquer Alaska at the cost of the Haida. Lead armies of thousands of troops to victory in large-scale battles in 10 missions. Both games are a real treat for any strategy fan. But this is not a standard RTS, there is no simple build-send-and-forget here because even the biggest army can be defeated by a well coordinated, but relatively small force. Just like the old proverb says: “An army of sheep led by a lion would defeat an army of lions led by a sheep.”' FROM games WHERE igdb_id = 9360 ON CONFLICT (game_id, language_code) DO NOTHING;
