INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pajama-sam-4-life-is-rough-when-you-lose-your-stuff', 10650, '2003-08-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ssq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arlcl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pajama Sam 4: Life Is Rough When You Lose Your Stuff!', 'Lost among the piles of clothes and toys is his prized comic book. Donning his red cape, Pajama Sam dives into the chaos only to land in a strange and fantastic world that resembles his messy room. Pajama Sam sets off on a series of adventures in search of his lost comic book, looking for lost socks in Agitator Lake, rounding up dust bunnies at the Dust Bunny Corral, exploring the Spilled Soda Swamp and much more. In the end, Sam finds his comic book and realizes that life wouldn''t be so rough if he put away his stuff! Throughout the story, kids meet lots of interesting new friends and tackle fun challenges that will inspire them to solve problems in creative ways.' FROM games WHERE igdb_id = 10650 ON CONFLICT (game_id, language_code) DO NOTHING;
