INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madden NFL 2004', 'The 2004 edition of Madden NFL Football includes several changes from the previous year. It features a complete list of NFL players and teams with statistics tracking. Multiple play modes include regular season, playoffs, and exhibition play. Create-a-player mode allows for the creation of a custom NFL player, which can be traded during a season.' FROM games WHERE igdb_id = 777 ON CONFLICT (game_id, language_code) DO NOTHING;
