INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Republic: The Revolution', 'Republic: The Revolution is a computer game produced by Elixir Studios, founded by Demis Hassabis , a former programmer of Lionhead Studios and published by Eidos Interactive. It has since been released for the Mac OS X by Feral Interactive. It is a depiction of grassroots political action, where one attempts to put their preferred government in power. It is set in Novistrana, a small, fictional, post-Soviet country in Eastern Europe.' FROM games WHERE igdb_id = 10236 ON CONFLICT (game_id, language_code) DO NOTHING;
