INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zuma Deluxe', 'An enhanced version, called Zuma Deluxe, was released for Microsoft Windows and Mac OS X as well as an Xbox Live Arcade download for the Xbox 360 and a PlayStation Network download for the PlayStation 3. It is also included with the PlayStation 3 retail version of Bejeweled 3, along with Feeding Frenzy 2. Survive the ancient temples of Zuma, the critically acclaimed action-puzzler from PopCap! Deep in the jungle lie hidden temples bursting with traps and trickery, and it''s up to you to uncover their treasures. Fire magical balls from your stone frog idol to make matches of three or more and clear the deadly chain before it reaches the golden skull. Think fast and aim smart, or you''ll be history in this action-packed puzzle challenge!' FROM games WHERE igdb_id = 20509 ON CONFLICT (game_id, language_code) DO NOTHING;
