INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nosferatu-the-wrath-of-malachi', 8960, '2003-10-21', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co256b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ypdzeowcyq86w6legtov.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nosferatu: The Wrath of Malachi', 'It is a misty evening in the year of our lord 1912. The Pattersons, a poor but proud aristocratic family of the British nobility, and some of their closest friends, arrive at the castle Malachi residence of a wealthy Romanian Count. It is only three days until the family''s eldest daughter, Rebecca, is to be wed to the count''s son, uniting the family with the rich heritage of the Malachi, hopefully restoring its glory. The only person missing is you, the brother of the bride, who is on your way from Stockholm, where you have defended the Union Jack in the noble art of fencing in the Olympics. You are to arrive later during the evening. Sir Patterson is disappointed when the Count himself doesn''t greet the family at their arrival, but still he lets the servants show them all to their rooms, without complaining too loudly. It is not until later--when the doors are slammed shut and locked behind them, that he realizes his mistake that they have become prisoners and are at the Count''s mercy...' FROM games WHERE igdb_id = 8960 ON CONFLICT (game_id, language_code) DO NOTHING;
