INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Rogue Squadron III - Rebel Strike', 'X-wings, B-wings, speeder bikes, AT-STs, tauntauns--you''ll have to master them all to save Luke, Wedge, Han, Chewie, and Leia from Darth Vader and his Imperial forces. All new multiplayer modes include the entire Rogue Leader game in co-op, plus endurance, capture-the-base, and dogfight modes. Cinematic realism takes you to new heights as you climb out of your cockpit to battle the Empire on foot in this thrilling third chapter of the Rogue Squadron series.' FROM games WHERE igdb_id = 4182 ON CONFLICT (game_id, language_code) DO NOTHING;
