INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman: Dark Tomorrow', 'Batman: Dark Tomorrow is an action-adventure video game developed by HotGen and published by Kemco for the Nintendo GameCube and Microsoft Xbox consoles. The Xbox version is not compatible with the Xbox 360. It is based on the DC Comics'' character Batman and his iteration from the DC Universe source material, unlike most other Batman games which are adaptations of the character in film or television appearances.' FROM games WHERE igdb_id = 5738 ON CONFLICT (game_id, language_code) DO NOTHING;
