INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Shooter', 'Alien Shooter is an top-down shooter video game from Sigma Team created in 2003. It is the first title in the Alien Shooter series to be followed by Alien Shooter: Vengeance. Alien Shooter has two expansions, Fight for Life and The Experiment. They each contain five new levels, including the conclusion to the alien shooter story.' FROM games WHERE igdb_id = 8634 ON CONFLICT (game_id, language_code) DO NOTHING;
