INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wario World', 'While Wario enjoys the riches from his many adventures, a mysterious black jewel in his trove transforms gems into monsters. Now, Wario must scramble to recover his riches in an alternate world filled with quirky puzzles, swarming enemies, and lots of loot. As Wario, you''ll punch, kick, jump, grab monsters and objects, and inhale surrounding coins like a vacuum cleaner. You must cling to 3D balls to fight bosses, find hidden areas through trap doors, and bash your surroundings to uncover secrets.' FROM games WHERE igdb_id = 1700 ON CONFLICT (game_id, language_code) DO NOTHING;
