INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vietcong', 271, '2003-03-26', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nmi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc63dy.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vietcong', 'Vietcong is an tactical FPS known for its realism focused gameplay and at the time, original Vietnam war setting. The game featured many early examples of later genre conventions such as iron sights and a cover system. In addition to the main story-driven campaign, the game also features a number of quick skirmish style missions for single player, as well as a fairly robust set of both cooperative and competitive multiplayer modes, including a downloadable set of coop missions entitled "Red Dawn" played from the perspective of Vietcong soldiers.' FROM games WHERE igdb_id = 271 ON CONFLICT (game_id, language_code) DO NOTHING;
