INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('teenage-mutant-ninja-turtles--1', 19747, '2003-10-21', 42, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2d6r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar86l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles', 'Teenage Mutant Ninja Turtles (2003) is a beat ''em up game based on the 2003 Teenage Mutant Ninja Turtles television series, following the events of a handful of season one episodes. The player can play as either Leonardo, Donatello, Michelangelo or Raphael. Each turtle has his own unique set of levels to complete. There is a story mode for one or two players, and there is also a versus mode where two players can fight head to head. In the versus mode, players can fight as all 4 turtles, Splinter, Casey Jones, Hamato Yoshi, The Turtlebot, Hun, Oroku Saki, and The Shredder. A Challenge mode is unlockable by defeating Oroku Saki with any Turtle in the Story Mode, which needs to be complete to unlock Hamato Yoshi and his dojo.' FROM games WHERE igdb_id = 19747 ON CONFLICT (game_id, language_code) DO NOTHING;
