INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ys VI: The Ark of Napishtim', 'Adventurer Adol Christin has washed ashore in yet another mysterious, isolated new land, inhabited by a people who sport long ears and bushy tails...and are none too fond of humans. Experience the very first 3D Ys game as never before, with a whole new gameplay mode unique to this release!' FROM games WHERE igdb_id = 15454 ON CONFLICT (game_id, language_code) DO NOTHING;
