INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xiii', 1987, '2003-11-18', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co87no.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2gfr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'XIII', 'XIII is a cel-shaded first-person shooter based on the popular Belgian cult comic created by Jean Van Hamme and illustrated by William Vance. The game is loosely based on the first five comics. The player unravels clues, trying to solve a conspiracy set in an environment that breathes a comic book ambiance. Footsteps and shots are visualized in text and actions: for example, headshots are shown in a series of still images. Aside from that, the game has all the typical FPS elements: both stealth and action, more than fifteen weapons (shotguns, crossbows, rifles, ...), interaction with environmental objects and plenty of enemies in levels spread all over the world. During the game, the player can learn a number of skills such as silent walking, lockpicking and dual weapons handling.' FROM games WHERE igdb_id = 1987 ON CONFLICT (game_id, language_code) DO NOTHING;
