INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pokemon-box-ruby-and-sapphire--1', 93046, '2003-05-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2sh1.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Box: Ruby & Sapphire', 'Pokémon Box: Ruby & Sapphire (Japanese: ポケモンボックス ルビー＆サファイア Pokémon Box Ruby & Sapphire) is a Nintendo GameCube Pokémon utility. Pokémon Box itself is not so much a game as it is a storage system for Trainers'' Pokémon. Trainers can store up to 1,500 Pokémon in twenty-five boxes that hold 60 Pokémon each and trade between Pokémon Ruby, Sapphire, and Emerald, as well as FireRed and LeafGreen. All of the Pokémon can be stored on a GameCube memory card, requiring the full 59 blocks for save data. A special edition Ruby and Sapphire Memory Card 59 is included with most versions of the game for players to use (the European version just comes with a normal memory card).' FROM games WHERE igdb_id = 93046 ON CONFLICT (game_id, language_code) DO NOTHING;
