INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spawn: Armageddon', 'Spawn: Armageddon is a 3D action/adventure game based on the comic by Todd McFarlane, who also contributed the storyline for the game. Spawn struggles between the forces of Heaven and Hell in order to save the world, equipped with his Hell-sent living symbiotic suit and its chains. A multitude of weapons and Hell Powers are also available. Agony, the axe that Spawn uses in SoulCalibur II is also available as a melee attack weapon.' FROM games WHERE igdb_id = 4160 ON CONFLICT (game_id, language_code) DO NOTHING;
