INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medal of Honor: Infiltrator', 'Medal of Honor Infiltrator puts you in the role of Corporal Jake Murphy, a man who must complete five daring missions to defeat the Axis powers in WWII. From sabotaging enemy resources to capturing key personnel to all-out firefights, you''ll need to master a variety of gameplay styles to overcome the enemy. On foot, in a tank, or even in disguise, you must engage opponents on the battlefield with an assortment of WWII-era weapons, including machine guns, grenades, bazookas, and more.' FROM games WHERE igdb_id = 1317 ON CONFLICT (game_id, language_code) DO NOTHING;
