INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'March! Offworld Recon', 'March! Offworld Recon is a first person shooter that takes place on Mars. When contact with a military research station is suddenly lost, a heavily armed reconnaissance team is sent to investigate. Quickly they uncover that all the robots on Mars have been brainwashed and have started murdering all the humans.' FROM games WHERE igdb_id = 92318 ON CONFLICT (game_id, language_code) DO NOTHING;
