INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lionheart: Legacy of the Crusader', 'Starting from humble beginnings as a slave, rise to fame and fortune by proving your self worthy against the terrible odds presented by your world''s realities and the recent crack in the fabric of reality. Face monstrous hordes and relentless bandits. Specialize in wielding cold steal or be a master of casting hot magical spells. Join factions to gain powerful allies and earn perks that will help you rise above the challenges.' FROM games WHERE igdb_id = 7505 ON CONFLICT (game_id, language_code) DO NOTHING;
