INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Links 2004', 'Links, the best-selling golf franchise for the personal computer, has been rebuilt—from the ground up—exclusively for the Xbox video game system. Links 2004 delivers one of the most realistic and competitive golf experiences for Xbox. Golf fans worldwide can compete online in friendly matches with old golfing buddies or compete in tournaments against the best golfers in the world via Xbox Live. Links 2004 also features top championship courses and top professionals, including cover athlete Sergio Garcia.' FROM games WHERE igdb_id = 5902 ON CONFLICT (game_id, language_code) DO NOTHING;
