INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spy Kids 3-D: Game Over', 'SpyKids 3-D: Game Over plunges kids inside the cyber world of a video game in 3-D with their favorite spies Carmen and Juni. Based on the movie of the same name, SpyKids 3-D: Game Over is available as two distinct games for Game Boy Advance and PC in July 2003 from Disney Interactive. The Game Boy Advance version is the first game with 3-D for this handheld platform. Both titles let kids crack secret codes that unlock rewards viewable with special Spy Kids 3-D: Game Over glasses that come with the game or theater showing the film.' FROM games WHERE igdb_id = 23693 ON CONFLICT (game_id, language_code) DO NOTHING;
