INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DTM Race Driver: Director''s Cut', 'This special edition of DTM Race Driver was specifically made for the German market. While it retains almost all of the same content as Pro Race Driver, it has full DTM licensing and also includes some exclusive cars. Some of the cars are the Opel Astra V8 Coupe, ABT-Audi TT-R, and the Mercedes-Benz CLK-DTM.' FROM games WHERE igdb_id = 73371 ON CONFLICT (game_id, language_code) DO NOTHING;
