INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kasparov-chessmate', 23528, '2003-01-05', 62, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ixtuznehwgosu849grby.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scz77e.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kasparov Chessmate', 'The game is backed by grand chessmaster, Garry Kasparov. Players can create a personal profile using their own name, MSN nickname for online/network play, country and a facial icon. Select a side black or white and game type: "Local" against the computer or other human to either no time limit or specified; "Online" via MSN Game Zone or over a computer network; and "Kasparov Chess Club" of 45 club members in a single "exhibition" game versus any member or "championship" to become Club Champion against all members each has different abilities and ratings ranging from Bronze to Gold with "hints" available during play. Actual play has accessible "history" record of all movement, option to "resign" or "draw" a game. The chessboard is viewable in 2D or 3D and styled as Staunton Black & White, Staunton Rosewood or Modern set with notation in algebraic or figurine. Movement is instant or adjustable by a slide for fast or slower paced game. For a novice unfamiliar with Chess, the "training" (tutorial) segment covers basic rules of play to winning. Strategies for openings and defenses to middle/end games. Useful tips, possible traps and problems. Review a selection of 64 historical games played by the grandmaster himself, Kasparov including famous matches against various top chess players to IBM''s supercomputer Deep Blue. Install or synchronize the game using a handheld device: Palm OS 3.5 or PocketPC docked in the cradle from Windows PC CD-ROM.' FROM games WHERE igdb_id = 23528 ON CONFLICT (game_id, language_code) DO NOTHING;
