INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bust-A-Move 3000', 'Everybody''s favorite bubble-bustin'' puzzle game is in the house for the Nintendo GameCube! Launch your bubbles and pop as many as you can before they reach the deadline. Score high by matching 3 bubbles or more to trigger a chain reaction. While the game play remains unchanged from Super Bust-A-Move, this version features new artwork and remixed music. The European and Japanese releases also include a new Space Invaders-style mini-game called "Shoot Bubble"' FROM games WHERE igdb_id = 50570 ON CONFLICT (game_id, language_code) DO NOTHING;
