INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Italian Job', 'Charlie Croker and his gang are left for dead in Venice after being double-crossed during one of the biggest gold heists ever. You must take on the role of Charlie and his gang members in their quest for revenge and the gold. Based on the film, The Italian Job''s story mode challenges you to create the largest traffic jam in LA history, and then escape in supercharged Mini Coopers. Master four other action-packed modes, including stunt driving, circuit racing, and multiplayer modes for up to two players.' FROM games WHERE igdb_id = 3959 ON CONFLICT (game_id, language_code) DO NOTHING;
