INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabela''s 4X4 Off-Road Adventure 3', 'Cabela''s 4X4 Off-Road Adventure 3 is a racing game with RPG elements, and is the third and final game in the series. Each completed mission has the player accumulate experience that allows for the purchase of better parts, newer trucks and the ability to accept tougher and more rewarding missions. Unlike other Cabela''s Off-Road titles, Off-Road 3 offers hunting with perspectives in and out of the truck.' FROM games WHERE igdb_id = 23702 ON CONFLICT (game_id, language_code) DO NOTHING;
