INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brute Force', 'The game is a squad-based third-person shooter that uses four members of a team who fight in numerous battles. Each character on the team has their own strengths and weaknesses. The story is of a science-fiction setting where humans spread throughout the galaxy and tension arises with the threat of a hostile alien race that appears. The squad, Brute Force, is sent in to confront the enemy.' FROM games WHERE igdb_id = 5759 ON CONFLICT (game_id, language_code) DO NOTHING;
