INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('metal-slug-5', 1410, '2003-11-01', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25th.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qfnicmn0c2rv5gsdpir3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Slug 5', 'A special disc that contains deep and intricate secrets about the Metal Slug project is stolen by a mysterious group called the Ptolemaic Army, whose specialty lies from within archaeological excavation and espionage. Marco and Tarma of the Peregrine Falcon Strike Force follow in hot pursuit against the group and in the process are joined by Eri and Fio of SPARROWS. Together once more, the quartet investigate the shrouded objective of the Ptolemaic Army.' FROM games WHERE igdb_id = 1410 ON CONFLICT (game_id, language_code) DO NOTHING;
