INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('buffy-the-vampire-slayer-chaos-bleeds', 3837, '2003-08-27', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3btt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm6od.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buffy the Vampire Slayer: Chaos Bleeds', 'Buffy and the crew are back for another battle against evil. On this occasion (set as a ''missing episode'' from the TV series'' fifth season), the powerful vampire Kakistos and The First are ready for war, and the only ones standing in their way is Buffy the Vampire Slayer and her friends Willow (an at times powerful witch), Faith (a fellow Slayer), Spike (former evil vampire turned slightly good) and Xander (caught in the middle of his best friends work). You get the chance to play as each character during the game as you slay vampires, solve puzzles and collect items along the way to prepare you for the final showdown. Various other characters from the show appear to help you out, while some are out to hurt you big time. Multiplayer options are also included for up to 4 players. Go rabbit hunting in Bunny Catch; be the last person standing against wave after wave of vamps in Survival or battle for control of the arena in Domination.' FROM games WHERE igdb_id = 3837 ON CONFLICT (game_id, language_code) DO NOTHING;
