INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('froggers-journey-the-forgotten-relic', 11480, '2003-11-28', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6hh9.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frogger''s Journey: The Forgotten Relic', 'In Frogger''s Adventure: Forgotten Relic, join Frogger on a fun-filled journey as he travels across diverse worlds, searches for clues and avoids fierce foes. Featuring Frogger''s Famous "hop-and-dodge" style gameplay, this game is designed to please players of all ages. There are also some elements that increase the replay of Frogger''s Journey: The Forgotten Relic, like the Castlevania: Harmony of Dissonance inspired furniture collection and the multiple paths unlocked by using the increasing abilities of Frogger. The game features almost 20 different levels and RPG-inspired gameplay on top of the classic Frogger formula.' FROM games WHERE igdb_id = 11480 ON CONFLICT (game_id, language_code) DO NOTHING;
