INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('romance-of-the-three-kingdoms-ix', 7492, '2003-05-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8q53.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Romance of the Three Kingdoms IX', 'The ninth release in KOEI''s Romance of the Three Kingdoms series casts players as rising rulers in ancient China and challenges them to unite the land under their rule. Following the basic design of earlier titles, players develop and manage large armies as they maneuver across the wide countryside, using both military force and diplomatic finesse to win territory and followers. The hard-core strategy framework is fleshed out with a variety of mission types, branching storylines, and an embellished adherence to the actual history and culture of the setting. Features in this edition include the ability to manage both political and military aspects of the empire, at the same time, allowing players to continue to negotiate while their troops are in battle. While this version of the game resumes the limitation that player characters must be of the Ruler class, officer development has been revised to allow greater control in developing followers. KOEI fans who also play Dynasty Warriors 4 and Dynasty Tactics 2 can use their save files to unlock a powerful, exclusive officer character. More than two-dozen Challenge scenarios, including 15 historical battles Use diplomacy and military might at the same time or shift strategies when appropriate More than 30 different tactics involving 12 military formations' FROM games WHERE igdb_id = 7492 ON CONFLICT (game_id, language_code) DO NOTHING;
