INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Haunted Mansion', 'The Disneyland attraction is making a video game appearance in The Haunted Mansion. In the famous house of wall-to-wall creeps and hot-and-cold running chills, you play Zeke, a boy burdened with the unenviable task of putting 999 evil spirits to rest while trying to keep himself from becoming number 1000.' FROM games WHERE igdb_id = 3945 ON CONFLICT (game_id, language_code) DO NOTHING;
