INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyblade VForce: Ultimate Blader Jam', 'A sinister group is stealing Bit Beasts from the World Champion Bladebreakers and you must help defend against this mysterious force, using skill, balance, and endurance. Play as any Bladebreakers--including Tyson and Kai, and call upon your best strategies and mightiest Bit Beasts. Unlock more than 100 Beyblade collectibles as you fight through 50 Vforce challenges. It''s a battle with the best Bladebreakers in the world, so make sure you''ve got the fighting spirit.' FROM games WHERE igdb_id = 49164 ON CONFLICT (game_id, language_code) DO NOTHING;
