INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Flight of the Falcon', 'Can you outrun the Empire? At last, you can know what it feels like to pilot the most popular ship in the Star Wars universe -- the Millennium Falcon. If you also want to find out what it feels like to wear super-tight pants and a black leather vest, that''s up to you. Star Wars: Flight of the Falcon challenges you to blast your way through the Empire''s fleet as you recreate the Battles of Yavin and Endor.' FROM games WHERE igdb_id = 6608 ON CONFLICT (game_id, language_code) DO NOTHING;
