INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cubix-robots-for-everyone-showdown', 3866, '2003-06-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ttg.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubix Robots for Everyone: Showdown', 'Cubix: Robots for Everyone - Showdown is a futuristic themed 3D action adventure game based on the Cubix: Robots for Everyone TV series. In the game the player takes control of either Connor or Abby and has to explore Bubble town by solving puzzles and battling robots. You have the ability to jump and move objects. The robot battles are turn-based and when won the robot is added to your battle team and can be used in the next battle. More than twenty-five robots can be collected. Cubix the main robot can transform into several vehicles. The game also includes mini-games that can be played with up to four players.' FROM games WHERE igdb_id = 3866 ON CONFLICT (game_id, language_code) DO NOTHING;
