INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Fighters EX2: Howling Blood', 'The King of Fighters EX2: Howling Blood is a fighting game released by Playmore, MMV and Sun-Tec for the Gameboy Advance. It is based on The King of Fighters 2000 and is the sequel of The King of Fighters EX. It was also ported for the N-Gage as The King of Fighters Extreme. Like its predecessor, The EX series takes place in an alternate timeline where the events of the NESTS Saga did not occur, as Kyo Kusanagi was found by Moe Habana rather than NESTS at the end of KOF ''97, thus this game took place instead of KOF 2000 in the EX continuity.' FROM games WHERE igdb_id = 49169 ON CONFLICT (game_id, language_code) DO NOTHING;
