INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Tower: Abyss', 'Shadow Tower Abyss is a dark fantasy role-playing video game, developed and published by From Software in Japan for the PlayStation 2. The game is a sequel to Shadow Tower, and features a number of genre and mechanical elements that can also be found in Demon''s Souls and the King''s Field series.' FROM games WHERE igdb_id = 9503 ON CONFLICT (game_id, language_code) DO NOTHING;
