INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Butt-Ugly Martians: Zoom or Doom', 'Butt-Ugly Martians: Zoom or Doom is a 2002 racing video game released by Runecraft. The game is based on the computer animated television series Butt-Ugly Martians. The gameplay of Zoom or Doom focuses mainly on competitive racing, there are seven different racers in which two have to be unlocked by the player, each with different advantages such as handling and speed. There is also a time attack mode, as well as a practice mode and multiplayer mode which allows the player to race with a friend. The game has no autosave feature, meaning the player has to manually save the game or else all progress will be lost.' FROM games WHERE igdb_id = 3841 ON CONFLICT (game_id, language_code) DO NOTHING;
