INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '5 Days a Stranger', '5 Days a Stranger is the first game in horror-adventure series by Ben "Yahtzee" Croshaw. Player controls Trilby, a master cat burglar, who gets trapped inside seemingly abandoned manor. Soon he finds out there are other captives as well and together they have to uncover shady past of the manor to be able to leave.' FROM games WHERE igdb_id = 79139 ON CONFLICT (game_id, language_code) DO NOTHING;
