INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pure Pinball', 'Pure Pinball contains three different 3D tables with their own themes (Racing, War and Trains) each featuring multiple flippers and special game modes. The game can be played from any of 12 different camera setups (for instance complete overview, ball close-up, ball follow or traditional scrolling style). This has been made possible through use of real-time 3D graphics. The game also features spot-on flipper control featuring a multiball enabled physics engine that calculates the ball movement more than 1500 times per second.' FROM games WHERE igdb_id = 5995 ON CONFLICT (game_id, language_code) DO NOTHING;
