INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kung Fu Chaos', 'Kung Fu Chaos is an entertaining brawler game inspired by the 70s Kung Fu movie era. You fight as one of nine characters--three of which are unlockable--with looks, moves, and taunts based on kung-fu movie icons. Your quest for movie stardom places you on a dynamic movie set, and when the director yells "Action!" you fight against multiple enemies either by yourself or with three friends. Perform over-the-top, Hong-Kong-style combat--including leaps, and flying kicks--and you''ll become a star in no time.' FROM games WHERE igdb_id = 5898 ON CONFLICT (game_id, language_code) DO NOTHING;
