INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Priston Tale', 'Priston Tale is a 3D MMORPG set in the fantasy world of Priston where you and other online players can join one of two main tribes to fight against a new evil that was prophesied to spread throughout. Focusing heavily on the action-element, this RPG boasts eight unique classes players can choose from - each having its own unique 5-tier skill set that upgrades as you progress your character.' FROM games WHERE igdb_id = 50856 ON CONFLICT (game_id, language_code) DO NOTHING;
