INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('g1-jockey-3', 23713, '2003-06-28', 62, 'https://images.igdb.com/igdb/image/upload/t_cover_big/roy4xoonsbpyusii3c0e.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'G1 Jockey 3', 'Fancy hats, oval turf tracks and people waving tiny bits of paper on the stands. Welcome to the world of horse racing. While most other racing games have the player controlling a motorized vehicle (such as a car or a powerboat), or using physics to move closer to the goal (skiing, sailing and so on), in G1 Jockey the player is controlling an animal, which makes it slightly different from other racing games in the market.  The player has to balance four things - the overall speed of the horse, the stamina, horse motivation, and the potential, which affects for how long the horse can keep the speed high after all stamina was lost - crucial for the last stretch sprint. It''s impossible to raise all four at once, so players must have a well defined strategy to succeed.  Depending on their abilities, each horse might be better suited for a particular strategy or type of race, and each must be treated differently to achieve the best possible result. The game features a large roster of horses, and many tracks to choose from, including flat track and steeplechase races. Game modes include race training, a tutorial, two player mode, and the career mode, where the player starts as a rookie jockey, and must complete races and training sessions to attract the attention of better stables.' FROM games WHERE igdb_id = 23713 ON CONFLICT (game_id, language_code) DO NOTHING;
