INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('apocalyptica', 22278, '2003-10-24', 30, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ty4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5wrh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apocalyptica', 'The forces of good and evil collide in this third-person gothic science fiction shooter. The single-player mode lets players select one of 16 characters and lead a team of holy avengers against the forces of Neo-Satan. Characters are skill rated and armed with guns, swords, and spells. Although the teammates and opponents are bots, each of the 18 levels is an objective based mission typical of multiplayer FPS games (rescue hostages, deliver packages, etc...). The player and bots re-spawn an unlimited number of times until the level objective is completed or failed. The forces of evil usually have a numerical advantage including a team of character type bots (comparable to the player''s team) and an additional horde of mindless minions.' FROM games WHERE igdb_id = 22278 ON CONFLICT (game_id, language_code) DO NOTHING;
