INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('motogp-3', 5938, '2003-02-27', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1oxh.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MotoGP 3', 'The gameplay is very similar to past games by Namco, like MotoGP (PS2) and MotoGP 2 (PS2). MotoGP 3 is based off the 2002 Grand Prix motorcycle racing season, but with the introduction of four stroke bikes, the gameplay has some slight differences. The new 990cc 4-stroke bikes are faster, but tend to be a bit of a handful while the 500cc 2-strokes are less faster but slightly better to handle.' FROM games WHERE igdb_id = 5938 ON CONFLICT (game_id, language_code) DO NOTHING;
