INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ghosthunter', 22279, '2003-12-05', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7lfo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq2ah.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghosthunter', 'Following the adventures of Lazarus Jones on his first day on the Detroit Police Force, Ghosthunter sees the plucky rookie called in to investigate a disturbance in an old abandoned school, the scene of a grisly (and ultimately unsolved) mass-murder. Heading out with his senior partner Anna Steele, Lazarus sets off on what he believes is a routine call but, in the true spirit of survival horror, it''s not long before the crime-bothering duo are knee-deep in ectoplasm. After much bickering between the pair, Jones somehow inadvertently sets free a horde of ghosts contained in the school''s secret paranormal research lab. An errant apparition materialises, grabs Anna, and drags her away with him to a dark, eerie place (the school canteen, perhaps?). One of the wayward spooks (Astral) also manages to ''bond'' with Jones, giving him the gift of supernatural sight, allowing him to see dead people. Nice. Picking up the reins as Laz, you''ll start out in search of Anna, and attempt to figure out the mysteries buried deep in the school''s past along the way...' FROM games WHERE igdb_id = 22279 ON CONFLICT (game_id, language_code) DO NOTHING;
