INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RoadKill', 'RoadKill is an open world action-adventure video game. It has been described as the only mission-based combat driving game set in a post-apocalyptic world. RoadKill is a vehicular combat game, and its gameplay is very similar to Twisted Metal, with a mission-based storyline and elements that share similarities to those from the Grand Theft Auto series.' FROM games WHERE igdb_id = 4089 ON CONFLICT (game_id, language_code) DO NOTHING;
