INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IndyCar Series', 'Codemasters'' official game, IndyCar Series, is blisteringly fast, nerve-shatteringly intense, pure professional racing and features ultra-close pack racing with up to 33 cars racing on track. Gameplay requires total focus to handle the incredible overtaking manoeuvres at speeds well over 220 mph. IndyCar Series delivers a full racing season, which includes the Indianapolis 500-Mile Race (Indy 500), the greatest spectacle in US racing.' FROM games WHERE igdb_id = 5866 ON CONFLICT (game_id, language_code) DO NOTHING;
