INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return to Castle Wolfenstein: Tides of War', 'Return to Castle Wolfenstein: Tides of War is an updated re-release for the Xbox based on the original PC version Return to Castle Wolfenstein. Next to the full, original singleplayer campaign, there are 7 new prologue levels that show how B.J. and Agent One first met and how they got captured and imprisoned at Wolfenstein Castle. There is also a secret bonus awarded at the end of every level when every secret area has been found.' FROM games WHERE igdb_id = 77220 ON CONFLICT (game_id, language_code) DO NOTHING;
