INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'This Is Football 2003', 'Soccer comes home as you lead your team to victory on or off the field. As a player, you''ll tackle, pass, and shoot winning goals from the field. As an owner, you''ll buy, sell, or trade players to create a winning team. More than 13,500 officially licensed FIFA pro players from 700 international and league teams compete in 10 stadiums around the globe. Your players can perform a variety of authentic moves, including high-flying headers, bicycle kicks, and goal-saving slide tackles.' FROM games WHERE igdb_id = 22067 ON CONFLICT (game_id, language_code) DO NOTHING;
