INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CSI: Crime Scene Investigation', 'What do a murdered woman, a slain police officer, and a mysterious arson case have in common? Enter the gritty world of CSI and search for the answer with Grissom, Catherine, and the entire Crime Scene Investigation team. As a new recruit, you''ll have to learn how to use all of the investigator tools, including cotton swabs, rubber gloves, and plaster molds.' FROM games WHERE igdb_id = 5795 ON CONFLICT (game_id, language_code) DO NOTHING;
