INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('planetside', 1829, '2003-05-20', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1s14.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rxhymldnp2qpdznw45vu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PlanetSide', 'PlanetSide chronicles the efforts of three factions as they fight for territorial control over ten different continents on the planet Auraxis. Players take on the role of individual soldiers fighting for one of the three factions within the game, and can specialize in various fields such as combat vehicle crewman, infantry, invisible infiltrator or a variety of combat support roles such as combat medic or combat engineer. The game is played primarily in a first person perspective, with the option of third-person. Unlike most shooting games, in which small-scale matches take place in essentially an instanced map, PlanetSide battles can involve hundreds of players in a single fight. PlanetSide battles concern control over territory and strategic points, and can cause repercussions to all three factions. To date, PlanetSide remains one of the few MMOFPS games ever created. A sequel, PlanetSide 2, was released in November, 2012. On January 24, 2014 Sony Online Entertainment announced that the game was going to be free-to-play in April 2014. The game was officially launched as free to play on April 29, after several delays. On July 1st 2016, at 4:00pm PT, Planetside servers went offline permanently.' FROM games WHERE igdb_id = 1829 ON CONFLICT (game_id, language_code) DO NOTHING;
