INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chessmaster', 23714, '2003-04-25', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qtk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmcmr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chessmaster', 'Chessmaster includes plenty of features to improve your chess skills, no matter what level you are. In Chess School, you can learn basic and advanced tactics before challenging computer-controlled opponents in single-player or multiplayer modes. The game includes a variety of gameplay modes, such as Quick Game, Rated Play, Handicap, Setup Position, and Puzzle. Watch as each piece attacks each other on the checkered battlefield. The iteration of the Chessmaster series on the PlayStation 2 contains most of the features available in the corresponding PC game - which, in this case, is Chessmaster 9000. You can play training games (with all the hints and analysis tools available), rated games (your rating changes after each play), puzzles (chess ones, not the "build the picture" type), learn chess by browsing through the hundreds of tutorials available in the Pandolfini''s Chess School or watch famous games. There are, however, some new features in the PS2 version; the most useful one is the Online mode. Other is the "living world" of the Chessmaster Championships, where the AI''s rating changes, too, as they play each other. The last one is more spectacular - a fantasy-themed - orcs vs. humans - game mode with animated chess sets and a 3D environment. You get to play chess in a forest, inside a castle and in the desert.' FROM games WHERE igdb_id = 23714 ON CONFLICT (game_id, language_code) DO NOTHING;
