INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Muscle: The Kinnikuman Legacy - The Path of the Superhero', 'BUMBLING BICEPS, the world of wrestling will never be the same! ...because now there''s a new Kid in town - Kid Muscle! His unwilling arrival on Earth comes conspicuously close to the legendary Muscle League Champions'' embarrassing beating at the hands of the d.M.p, a devious new breed of evil wrestling super villains. The Muscle League has recruited King Muscle''s own son to reinvigorate their falling fortunes! And they''ve enlisted and trained a whole new generation of heroes to take on the diabolical d.M.p and save the planet!!' FROM games WHERE igdb_id = 49208 ON CONFLICT (game_id, language_code) DO NOTHING;
