INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-drive-d-masters-shot', 3897, '2003-03-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ir8.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Drive: D-Masters Shot', 'Dragon Drive: D-Masters Shot is a third-person shooter video game released in 2003 by Treasure Co. Ltd. The game is based on the Dragon Drive series and was only released in Japan. Gameplay[edit] Dragon Drive was an aerial combat game, set primarily in large, outdoor arenas where players had to face several waves of enemies. With multi-directional dash and lock on abilities, the game has sometimes drawn comparisons to the Zone of the Enders series. The game also has a handful of rail shooter levels, drawing frequent comparisons to Sega''s Panzer Dragoon series, but these comprise only a very small portion of the game.' FROM games WHERE igdb_id = 3897 ON CONFLICT (game_id, language_code) DO NOTHING;
