INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anito: Defend A Land Enraged', 'Anito is a Single-Player Isometric Adventure RPG game by Anino Entertainment, an independent video game company based in the Philippines, set in 16th century Asia, in the land of Maroka. Maroka is an island besieged both by internal conflict and armored invaders from a faraway land who are slowly turning Maroka into their monarch''s colony. When Datu Maktan, leader of the Mangatiwala tribe and the land''s most influential peacemaker, mysteriously disappears, it is up to his children Agila and Maya to find him and restore the delicate peace that their father has kept in balance, before conlicting forces tear the land apart.' FROM games WHERE igdb_id = 24106 ON CONFLICT (game_id, language_code) DO NOTHING;
