INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Five-O', 'Take on the role of Ninja Five-O as he uses all his skill, stealth and magic to rescue hostages and defeat his enemies. Master the art of ninja swords, shuriken throwing stars and ancient ninjitsu magic! * Kaginawa Wire grappling hook that can be used to hang, fly, jump, climb walls and surprise attack. * 6 Challenging missions covering 20 levels. * Crush objects to find hidden Power-Ups and secret items * Unique enemy boss characters for each level.' FROM games WHERE igdb_id = 6524 ON CONFLICT (game_id, language_code) DO NOTHING;
