INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NBA Inside Drive 2004', 'Real-time, 3D NBA basketball simulation with online league capabilities. More responsive "juke" controls for one-on-one isolation moves. Gamers can play up to 25 NBA seasons with full general management capabilities. All-new Drive Cam camera angle brings the player closer to the action. For 1 or more players (online gaming requires Internet connection). Features 3D crowd.' FROM games WHERE igdb_id = 24124 ON CONFLICT (game_id, language_code) DO NOTHING;
