INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corvette', 'Corvette lets you race a variety of Corvettes on the open road or in super speedways. The game includes more than 120 production Corvette models from 1953 to 2003, plus show and race cars. Choose a car, official car color, and a driver, and then race on tracks or an obstacle-filled Route 66. Upgrade your car''s engine and suspension for more realistic physics.' FROM games WHERE igdb_id = 5788 ON CONFLICT (game_id, language_code) DO NOTHING;
