INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tonka: Rescue Patrol', 'Be the hero of the town as you patrol its streets and lend a hand in Tonka rescue and construction vehicles. In customizable cars, trucks, and helicopters, you''ll explore five different environments that expand as you play. You can customize your vehicles to suit your style of play and perform jumps and other stunts on the free-roaming landscape. Tonka Rescue Patrol features realistic rescue missions with Tonka Joe as your guide.' FROM games WHERE igdb_id = 4202 ON CONFLICT (game_id, language_code) DO NOTHING;
