INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Victoria: An Empire Under the Sun', 'Carefully guide your nation from the era of absolute monarchies in the early 19th century, through expansion, colonization and social upheaval, to emerge as one of the great world powers by the dawn of the 20th century in Victoria. Gather the wealth and strength required to stay ahead of your enemies, gain invaluable prestige and honor, and reform the nation into a free democracy. Or, drive your people down the grim road of tyranny, corruption, and anarchy...' FROM games WHERE igdb_id = 11036 ON CONFLICT (game_id, language_code) DO NOTHING;
