INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CT Special Forces 2: Back in the Trenches', 'Despite their latest failures, the CT Special Forces unit is called upon once again to diffuse increased terrorist activity around the globe. Armed with high-tech weaponry and equipment, you must thwart the plans of terrorist groups and ensure peace in several regions of the world. You''ll have access to an array of vehicles and weapons, including shotguns, bazookas, sniper rifles, and more. CT Special Forces 2 lets you prove your combat skills in a variety of single-player and multiplayer modes.' FROM games WHERE igdb_id = 6353 ON CONFLICT (game_id, language_code) DO NOTHING;
