INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medabots Infinity', 'Medabots Infinity is a role-playing video game published in 2003 by Natsume, and developed by Victor Interactive. The game is based on the Medabots series. Hooking up to the Metabee and Rokusho Game Boy Advance games allows for secret unlockable medabots: Arcbeetle (Metabee) and Mega-Emperor (Rokusho). Several characters from the anime make appearances' FROM games WHERE igdb_id = 3999 ON CONFLICT (game_id, language_code) DO NOTHING;
