INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Crisis 3', 'Dino Crisis 3 is a survival horror video game released exclusively for the Xbox. It is the fourth and final game in the Dino Crisis series. Like the previous iterations of the series, gameplay revolves around fighting dinosaurs. Unlike the first three installments of the Dino Crisis series, the enemies in the game are not real-world dinosaurs, but new species created through advanced genetic engineering technology. The action takes place in outer space, on a starship, the Ozymandias.' FROM games WHERE igdb_id = 5813 ON CONFLICT (game_id, language_code) DO NOTHING;
