INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SWAT: Global Strike Team', 'SWAT: GST is a first-person tactical arcade game combining the strategic elements of SWAT 3 with the instantly accessible arcade action of the Virtua Cop series. Like the real-life SWAT organization itself, the SWAT Global Strike Team is a life-saving organization tasked with defending and saving the lives of the innocent. As a member of the SWAT Global Strike Team gamers will be called to duty at a moment?s notice, confronted with missions unlike any seen before. Founded in 2008, The Global Strike Team is an international offshoot from the SWAT organization tasked with helping countries and organizations around the globe to resolve situations they cannot accomplish successfully on their own.' FROM games WHERE igdb_id = 314 ON CONFLICT (game_id, language_code) DO NOTHING;
