INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tenchu: Wrath of Heaven', 'Move like a shadow. Strike like a snake. After amassing an army of ninjas and lords of darkness, the mysterious Tenrai has begun a quest to conquer 16th-century Japan. Now your master, Lord Gohda, has called upon you - a cunning stealth assassin - to stop Tenrai and his disciples before all is lost. Live by honor. Kill by stealth.' FROM games WHERE igdb_id = 6194 ON CONFLICT (game_id, language_code) DO NOTHING;
