INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('enter-the-matrix', 1003, '2003-05-14', 56, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1oum.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qfu4nvzumb1ooe0nrorl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enter the Matrix', 'Enter the Matrix is the first video game based on The Matrix series of films. Its story was concurrent with that of The Matrix Reloaded, and featured over an hour of original footage, directed by The Wachowskis and starring the cast of the film trilogy, produced exclusively for the game. It sold one million copies in its first eighteen days of release, 2.5 million over the first six weeks, and ultimately 5 million copies. First released in May 2003, the same month as The Matrix Reloaded, Enter the Matrix was simultaneously produced with The Matrix Reloaded and The Matrix Revolutions. It was developed by Shiny Entertainment, published by Atari and distributed by Warner Bros. Interactive Entertainment for the GameCube, Microsoft Windows, PlayStation 2 and Xbox.' FROM games WHERE igdb_id = 1003 ON CONFLICT (game_id, language_code) DO NOTHING;
