INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mlb-slugfest-2004', 23819, '2003-03-17', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7l5c.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB SlugFest 2004', 'The second title in Midway''s baseball series, SlugFest 20-04 continues to pour on the rough-housing gameplay, bizarre codes, and humorous commentary. In addition to the new Home Run Derby mode and Create-A-Team options, the game features the ability of pitchers to catch "On Fire" and impossible Special Pitches that zigzag, arc, and whizz by in ways that would leave any batter humiliated. New secret teams have been added to the previous bunch, including aliens, minotaurs, and Sub-Zero of Mortal Kombat fame. The customizable Instant Replay is another nice touch, allowing you to relive the awkward moments once you pause the game. And, of course, Tim Kitzrow and Jim Shorts return to the commentators'' booth, making their signature random comments and incessant arguments.' FROM games WHERE igdb_id = 23819 ON CONFLICT (game_id, language_code) DO NOTHING;
