INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bloody-roar-4', 24104, '2003-11-11', 86, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nn7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1sjd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloody Roar 4', 'During the XGC (X-Genome Code) Incident one year ago, riots raged over the earth by beasts that did not show the XCG, and all over the country small earthquakes shook the land. The cause was unknown, but as the Crest Incident came to an end and the rioting and earthquakes subsided, people began to claim that all was due to the influence of the Stone Seal. Although the Stone Seal has been locked away, the rioting and earthquakes have returned. This time, the incidents are on a larger scale than those of a year ago. What could be behind it all? Bloody Roar 4 is the last title in the series, and is once again a full-3D fighting game featuring the series'' trademark transformation abilities. Unlike previous titles in the series, the beast gauge now acts as its own health bar; if a character''s health gauge is depleted, they will automatically transform. The game features 18 playable fighters and a variety of game modes, including standard arcade, versus, time-attack, training, and survival modes. Of special mention is the career mode, in which fighting battles will earn so-called "DNA points," which can be spent on abilities and equipment to customize a character for use in other modes.' FROM games WHERE igdb_id = 24104 ON CONFLICT (game_id, language_code) DO NOTHING;
