INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: Lament of Innocence', 'Leon Belmont, an eleventh-century nobleman and knight of the clergy, is about to be wed when his fiancée, Sara Trantoul, suddenly disappears. Leon embarks on an epic journey to bring her back, unaware that a growing evil looms like a shadow over his quest. The majestic tale of Castlevania and the true origins of the Belmont clan of vampire-hunters is about to unfold.' FROM games WHERE igdb_id = 1135 ON CONFLICT (game_id, language_code) DO NOTHING;
