INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Championship Snooker 2003', 'The chart-busting success of World Championship Snooker returns for a new year and a new snooker challenge. Veteran snooker fans and championship newcomers step up to the table in opposition to Stephen Hendry, Peter Ebdon, Mark Williams, Ronnie O’Sullivan and more than twenty top players from the world of professional snooker. With incredible enhancements in every area of the game, plus new game modes and a more compelling snooker experience than ever before, World Championship Snooker 2003 is set to make the big breaks frame after frame.' FROM games WHERE igdb_id = 14547 ON CONFLICT (game_id, language_code) DO NOTHING;
