INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hot-wheels-world-race', 10626, '2003-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6is1.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Wheels World Race', 'In Hot Wheels Highway 35 World Race, racing is taken to a new level as players are thrust into the unique futuristic Hot Wheels fantasy world where life revolves around the most intense stunt racing ever imagined. Players race against the clock on extreme tracks featuring split/multi-level courses, obstacles and speeds unlike anything ever experienced before. Players will be able to pull-off wild gravity-defying stunts, speed through huge loops, drive up walls, find hidden shortcuts or simply just race opponents through volcanoes, ice, mountains and more. The game lets players choose from authentic Hot Wheels cars.' FROM games WHERE igdb_id = 10626 ON CONFLICT (game_id, language_code) DO NOTHING;
