INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Brother Bear', 'Brother Bear allows players to play as Kenai and Koda, individually or as a team, as they go on an adventure that follows the beats of the film. The game features elements such as spectacular weather effects and cut-scenes from the film which will bring alive the world of Brother Bear. With four worlds, 16 levels and unlockable bonus games, Disney''s Brother Bear for the GBA is a game of epic proportions.' FROM games WHERE igdb_id = 49409 ON CONFLICT (game_id, language_code) DO NOTHING;
