INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil Outbreak', 'Resident Evil Outbreak is a survival-horror game released exclusively for the PlayStation 2. The gameplay is similar to the previous Resident Evil games and consists mainly of exploring, solving puzzles, finding items and surviving. It was the first Resident Evil game with multiplayer capability, using the PlayStation 2''s online network. Up to four players could participate simultaneously in one scenario. Alternately, in single-player mode, the player is accompanied by two AI-controlled characters.' FROM games WHERE igdb_id = 972 ON CONFLICT (game_id, language_code) DO NOTHING;
