INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Extreme Skate Adventure', 'Disney characters step out of the movies and onto skateboards in Disney''s Extreme Skate Adventure. You can play as your favorite Disney and Pixar characters, such as Buzz Lightyear and Woody from Toy Story 2, Simba and Rafiki from The Lion King, and Young Tarzan and Terk from Tarzan. Now you can skate, pull off tricks, and solve puzzles in all the exciting places you''ve seen in the movies, including Pride Rock, the Jungle Treehouse, and Pizza Planet.' FROM games WHERE igdb_id = 3883 ON CONFLICT (game_id, language_code) DO NOTHING;
