INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('all-star-baseball-2004', 11558, '2003-02-25', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6dlj.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All-Star Baseball 2004', 'The 2004 installment in Acclaim''s long-running baseball series. The game features more than 80 new features and improvements, including a deeper, more customizable franchise mode. The biggest change comes in the interface. You still hit the same buttons to swing, bunt, steal, and field, but the batting cursor has been visually altered. It''s still the same triangle shape as before, just with a different outline. Bunting is more unique, though. Instead of aiming the cursor when you go to bunt, a large arrow points on the ground. Aim your bunt in the desired direction and hope for the best. Fielding has also received a slight change, with the ball cursor changing color. Four up to four players.' FROM games WHERE igdb_id = 11558 ON CONFLICT (game_id, language_code) DO NOTHING;
