INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Jack: The Amulet of Time', 'Samurai Jack is a warrior who is banished by the shape-shifting wizard Aku into the bizarre and twisted future. Bearing his new futuristic name, Jack wanders the land searching for a portal back in time to right the wrongs of the past. He has learned of a mysterious Amulet that, when all its pieces are found, will enable him to return to the past.. Join Samurai Jack on a journey of honor and revenge through a futuristic world filled with wonders and help him rid the world of evil once and for all.' FROM games WHERE igdb_id = 2822 ON CONFLICT (game_id, language_code) DO NOTHING;
