INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Return to Castle Wolfenstein: Operation Resurrection', 'Operation Resurrection is the PlayStation 2 version of the Return to Castle Wolfenstein with some added extras that make it it''s own unique game. Next to the full, original singleplayer campaign, there are 7 new prologue levels that show how B.J. and Agent One first met and how they got captured and imprisoned at Wolfenstein Castle. There is also a secret bonus awarded at the end of every level when every secret area has been found. Unlike Return to Castle Wolfenstein: Tides of War there is no multiplayer support - internet and multi link.' FROM games WHERE igdb_id = 77219 ON CONFLICT (game_id, language_code) DO NOTHING;
