INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('big-rigs-over-the-road-racing', 7557, '2003-11-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9k6j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ecz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Rigs: Over the Road Racing', 'Big Rigs: Over the Road Racing (often simply referred to as Big Rigs) is a 2003 third-person racing video game developed by Stellar Stone and published by GameMill Publishing for Microsoft Windows PC systems. The game was released as a largely unfinished product and many parts of it do not work properly at all. The packaging of Big Rigs states that the main objective of the game is to race a semi-trailer truck (known colloquially as a "big rig") in order to safely deliver illegal cargo being carried by the vehicle, while avoiding the local police force. In actuality, there are no police in the game, no such objectives are presented within the game itself and there is no load attached to the truck.[1] Much of the game instead centers on the player racing their truck against fellow drivers to the finish line; however, in the earlier versions the player''s computer-controlled opponent vehicles have no AI and never move from the starting position. In a later version, the computer-controlled opponent will race around the track, but will stop just before crossing the finish line. The timer in the game is merely aesthetic and has no limit on the gameplay. In addition, due to a lack of collision detection, there are no obstacles to navigate within the game, and the player is able to phase through environments and leave the game altogether. Big Rigs: Over the Road Racing was critically panned. The game''s criticism is largely directed at its "blatantly unfinished"[2] state: lack of collision detection and frequent violation of the laws of physics, frequent and major software bugs, poor visuals, and severe lack of functionality. As a result, the game is now widely regarded as one of the worst video games of all time' FROM games WHERE igdb_id = 7557 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 7557 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
