INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trainz Railroad Simulator 2004', 'In this 3D railroad simulator, you can operate locomotives from the golden age of steam to the modern present in realistic scenarios, to move goods and resources from one place to another and keep the wheels of industry turning. You are in charge of every aspect of the process: complete control over the orders of the drivers, limits for the transportation process, the movement of the passengers and freight and a custom scripted system to create your own rules.' FROM games WHERE igdb_id = 11013 ON CONFLICT (game_id, language_code) DO NOTHING;
