INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moorfrog', 'This adaptation of Frogger has Crazy Chicken 3''s original Moorfrog character traverse various streets and rivers to reach his spawning ground, having to evade larger animals or man-made objects while eating insects to increase the score. On November 20, 2004 an official patch was released that added an infinite arcade mode.' FROM games WHERE igdb_id = 93346 ON CONFLICT (game_id, language_code) DO NOTHING;
