INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball', 'The game is a remake of the 1989 game Dragon Ball 3: Gokuden with improved graphics and sound. It relates all the Dragon Ball story until the fight against Piccolo Junior. The main character is Goku as a child and as an adult, though Krillin and Yamcha are also playable characters in one battle.' FROM games WHERE igdb_id = 38662 ON CONFLICT (game_id, language_code) DO NOTHING;
