INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('conflict-desert-storm-ii-back-to-baghdad', 3864, '2003-09-19', 63, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coas1p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4l9w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conflict: Desert Storm II: Back to Baghdad', 'Take charge of the most feared special operations forces in the world: the elite British SAS or the US Delta Force squads. You''re the best trained, best equipped and best organised. The area that has been assigned to you is yours for the taking. Seek, locate and destroy enemy targets and personnel. Create havoc and confusion throughout the enemy''s lines of communication and supply. What lies before you is the opportunity of a soldier''s lifetime. Take your equipment, take your training and use it well. Squad-based combat over 15 challenging missions.Key Features:Control a squad of four expert SAS or Delta Force operatives - Team Leader, Sniper, Heavy Weapons Specialist and Combat Engineer. Call in air strikes, take control of vehicles and engage in the most fearsome combat you will ever face. Watch your squad''s expertise improve as each mission is completed. Unprecedented AI governs enemy and squad behaviour. Multiple paths through 15 challenging missions in urban, desert and indoor environments. Real-World physics and ballistic models accurately simulate the rigours of combat. Superb sound effects, explosions and actual Special Forces weaponry.' FROM games WHERE igdb_id = 3864 ON CONFLICT (game_id, language_code) DO NOTHING;
