INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Homeworld 2', 'Homeworld 2 is the third game in the Homeworld series. Although well-received and praised for its lavish graphics, Homeworld 2 did not receive the same level of acclaim as Homeworld 1 or Cataclysm. Patches and an active modding community has helped keep Homeworld 2 popular until its re-release by Gearbox Software in 2015.' FROM games WHERE igdb_id = 750 ON CONFLICT (game_id, language_code) DO NOTHING;
