INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Hide and Sneak', 'Either Mickey or Minnie will get kidnapped by a strange flying alien mushroom - depending on who the players chooses to control. Now the other character has to undertake a rescue mission. Gameplay includes climbing, solving puzzles, jumping, evading and hiding from enemies. Enemies can be taken out when sneaking close enough to enemies. As you make progress you traverse three game areas. These are a warehouse, museum and ruins.' FROM games WHERE igdb_id = 3885 ON CONFLICT (game_id, language_code) DO NOTHING;
