INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robot Arena 2: Design and Destroy', 'Robot Arena: Design & Destroy is a PC game of robotic construction and combat. It is a sequel to the original Robot Arena. It''s a simulation/arcade game based on robotic combat like you see on television. Robot Arena: Design & Destroy has more weapons, more accessories, more ACTION! Powered by the Havok Hardcore physics engine, bots can now bounce, flip, twirl and arenas are no longer just a flat box.' FROM games WHERE igdb_id = 8854 ON CONFLICT (game_id, language_code) DO NOTHING;
